#!/usr/bin/env python3
"""
INFERNO  -  משחק יריות בגוף ראשון בסגנון Doom, ב-Python
==========================================================
מנוע raycasting מלא ב-numpy: קירות, רצפה ותקרה עם טקסטורות,
תאורה דינמית צבעונית (לפידים, מנורות, לבה, כדורי אש, הבזק לוע),
ערפל, וינייט, חלקיקים, ושני סוגי שדים מוצללים בתלת-ממד.
כל הגרפיקה והסאונד נוצרים בקוד - אין צורך בקבצים חיצוניים.

התקנה:  pip install pygame numpy
הרצה:   python inferno.py

שליטה:
  W A S D     - תנועה           עכבר / חצים - הסתובבות
  Shift       - ריצה            קליק / רווח - ירייה
  1 / 2 / 3   - החלפת נשק (או Q/E, גלגלת)
  Tab         - מפה מלאה (מפה קטנה תמיד בפינה)
  R           - משחק חדש
  M           - השתקת צלילים
  Esc         - חזרה לתפריט
"""
import math
import random
import sys
from array import array

import numpy as np
import pygame

# ======================================================================= הגדרות
WIN_W, WIN_H = 960, 640
HUD_H = 100
VIEW_H = WIN_H - HUD_H            # 540
RW, RH = 480, 270                 # רזולוציית רינדור פנימית (מוגדלת פי 2)
FOV = math.radians(72)
PLANE = math.tan(FOV / 2)
FOCAL = (RW / 2) / PLANE
T = 128                           # גודל טקסטורה
TM = T - 1
FPS = 60
F32 = np.float32
AMBIENT = np.array([0.14, 0.115, 0.12], F32)
FOG = np.array([0.045, 0.02, 0.025], F32)
FOG_DENSITY = 0.075
MAX_LIGHTS = 7

CAMX = (2 * (np.arange(RW) + 0.5) / RW - 1).astype(F32)
YS = (np.arange(RH, dtype=F32) + 0.5)[None, :]

