def is_heb(c):
    return "\u0590" <= c <= "\u05ff"


MIRROR = {"(": ")", ")": "(", "[": "]", "]": "[", "<": ">", ">": "<", "{": "}", "}": "{"}


def bidi(s):
    """המרה פשוטה של טקסט עברי לסדר תצוגה (pygame לא תומך בכתיבה מימין לשמאל)."""
    if not any(is_heb(c) for c in s):
        return s
    types = []
    for c in s:
        if is_heb(c):
            types.append("R")
        elif c.isascii() and (c.isalnum() or c in "+%#/"):
            types.append("L")
        else:
            types.append("N")
    n = len(s)
    for i in range(n):        # תו ניטרלי בין שני תווים לועזיים נשאר לועזי
        if types[i] == "N":
            j = i
            while j < n and types[j] == "N":
                j += 1
            left = next((types[k] for k in range(i - 1, -1, -1) if types[k] != "N"), "R")
            right = types[j] if j < n else "R"
            for k in range(i, j):
                types[k] = "L" if left == right == "L" else "R"
    runs = []
    for c, t in zip(s, types):
        if runs and runs[-1][0] == t:
            runs[-1][1].append(c)
        else:
            runs.append([t, [c]])
    out = []
    for t, chars in reversed(runs):
        if t == "R":
            out.extend(MIRROR.get(c, c) for c in reversed(chars))
        else:
            out.extend(chars)
    return "".join(out)


# ======================================================================= עזרים


def norm_angle(a):
    return (a + math.pi) % (2 * math.pi) - math.pi


def value_noise(size, cells, rng):
    g = rng.random((cells, cells)).astype(F32)
    x = np.arange(size, dtype=F32) * cells / size
    i0 = x.astype(int)
    f = x - i0
    i1 = (i0 + 1) % cells
    f = f * f * (3 - 2 * f)
    a, b = g[i0][:, i0], g[i0][:, i1]
    c, d = g[i1][:, i0], g[i1][:, i1]
    fy, fx = f[None, :], f[:, None]
    return (a * (1 - fy) + b * fy) * (1 - fx) + (c * (1 - fy) + d * fy) * fx


def fbm(size, rng, base=4, octaves=5):
    out = np.zeros((size, size), F32)
    amp, tot = 1.0, 0.0
    for o in range(octaves):
        cells = base * 2 ** o
        if cells > size:
            break
        out += value_noise(size, cells, rng) * amp
        tot += amp
        amp *= 0.5
    return out / tot


def grid_xy(n=T):
    return np.meshgrid(np.arange(n, dtype=F32), np.arange(n, dtype=F32), indexing="ij")


def emboss(h, k):
    """הצללת תבליט ממפת גובה - אור מלמעלה-שמאל."""
    gx = np.roll(h, -1, 0) - np.roll(h, 1, 0)
    gy = np.roll(h, -1, 1) - np.roll(h, 1, 1)
    return np.clip(1 + (gx + gy) * k, 0.25, 1.9)[..., None]


# ======================================================================= טקסטורות


def tex_brick(rng):
    X, Y = grid_xy()
    bh, bw = 32, 64
    row = (Y // bh).astype(int)
    xo = (X + (row % 2) * (bw // 2)) % T
    col = (xo // bw).astype(int)
    lx, ly = xo % bw, Y % bh
    e = np.minimum(np.minimum(lx, bw - 1 - lx), np.minimum(ly, bh - 1 - ly))
    h = np.clip((e - 2) / 4, 0, 1)
    n = fbm(T, rng, 4, 6)
    tone = rng.uniform(0.7, 1.15, (T // bh, 3))[row, col][..., None]
    brick = np.array([0.55, 0.27, 0.18], F32) * tone * (0.6 + 0.65 * n[..., None])
    mortar = np.array([0.2, 0.18, 0.16], F32) * (0.7 + 0.5 * n[..., None])
    rgb = np.where((h > 0)[..., None], brick, mortar)
    rgb = rgb * emboss(h + n * 0.4, 0.9)
    rgb *= 1 - np.clip((Y - 92) / 36, 0, 1)[..., None] * 0.5     # לכלוך בתחתית
    return rgb, np.zeros_like(rgb)


def tex_tech(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    streak = rng.random(T).astype(F32)
    streak = ((streak + np.roll(streak, 1)) * 0.5)[None, :]
    rgb = np.array([0.36, 0.40, 0.45], F32) * (0.75 + 0.25 * streak[..., None] + 0.25 * n[..., None])
    px = np.minimum(X % 64, 63 - X % 64)
    py = np.minimum(Y % 64, 63 - Y % 64)
    h = np.clip((np.minimum(px, py) - 1) / 3, 0, 1)
    for cx in (7, 57, 71, 121):
        for cy in (7, 57, 71, 121):
            h = h + np.clip(1 - np.hypot(X - cx, Y - cy) / 3, 0, 1) * 0.9
    vent = (X > 74) & (X < 118) & (Y > 12) & (Y < 52)
    h = np.where(vent & ((Y % 6) < 3), h - 0.6, h)
    em = np.zeros((T, T, 3), F32)
    strip = (X >= 14) & (X < 114) & (Y >= 98) & (Y < 104)
    hazard = Y >= 112
    rgb = rgb * emboss(h, 1.1)
    stripes = (((X + Y) // 10) % 2 == 0)
    rgb = np.where((hazard & stripes)[..., None], np.array([0.7, 0.55, 0.08], F32) * (0.8 + 0.3 * n[..., None]), rgb)
    rgb = np.where((hazard & ~stripes)[..., None], rgb * 0.25, rgb)
    glow = np.array([0.25, 1.6, 0.7], F32)
    rgb = np.where(strip[..., None], np.array([0.5, 1.0, 0.7], F32), rgb)
    em = np.where(strip[..., None], glow, em)
    return rgb, em


def tex_rock(rng):
    n = fbm(T, rng, 4, 6)
    n2 = fbm(T, rng, 4, 5)
    ridge = 1 - np.abs(2 * n2 - 1)
    rgb = np.array([0.34, 0.15, 0.1], F32) * (0.35 + 1.0 * n[..., None])
    rgb = rgb * emboss(n * 2.0, 1.4)
    crack = np.clip((ridge - 0.9) / 0.08, 0, 1)[..., None]
    rgb = rgb * (1 - crack) + crack * np.array([0.9, 0.45, 0.1], F32)
    em = crack * np.array([2.4, 0.8, 0.1], F32)
    return rgb, em


def tex_stone_floor(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    tx, ty = (X // 64).astype(int), (Y // 64).astype(int)
    tone = rng.uniform(0.75, 1.1, (2, 2))[tx, ty][..., None]
    e = np.minimum(np.minimum(X % 64, 63 - X % 64), np.minimum(Y % 64, 63 - Y % 64))
    h = np.clip((e - 1) / 3, 0, 1)
    rgb = np.array([0.42, 0.38, 0.34], F32) * tone * (0.55 + 0.7 * n[..., None])
    rgb = np.where((h > 0)[..., None], rgb, rgb * 0.25)
    return rgb * emboss(h + n * 0.5, 0.8), np.zeros((T, T, 3), F32)


def tex_metal_floor(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    a = ((X + Y) % 16) - 8
    b = ((X - Y) % 16) - 8
    h = np.clip(1 - (np.abs(a) / 2.5 + np.abs(b) / 6), 0, 1)
    rgb = np.array([0.33, 0.35, 0.37], F32) * (0.7 + 0.4 * n[..., None])
    return rgb * emboss(h, 1.3), np.zeros((T, T, 3), F32)


def tex_lava(rng):
    n = fbm(T, rng, 4, 6)
    n2 = fbm(T, rng, 8, 4)
    hot = np.clip((n - 0.38) * 2.6 + (n2 - 0.5) * 0.6, 0, 1)[..., None]
    crust = np.array([0.12, 0.05, 0.04], F32) * (0.6 + n2[..., None])
    rgb = crust * (1 - hot) + hot * np.array([1.0, 0.5, 0.1], F32)
    em = hot ** 1.5 * np.array([3.0, 1.15, 0.18], F32) + np.array([0.15, 0.03, 0.0], F32)
    return rgb, em


def tex_ceiling(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    e = np.minimum(np.minimum(X % 64, 63 - X % 64), np.minimum(Y % 64, 63 - Y % 64))
    h = np.clip((e - 2) / 4, 0, 1)
    rgb = np.array([0.27, 0.25, 0.26], F32) * (0.6 + 0.6 * n[..., None])
    rgb = np.where((h > 0)[..., None], rgb, rgb * 0.3)
    return rgb * emboss(h, 0.7), np.zeros((T, T, 3), F32)


# ---------------------------------------------------------------- טקסטורות חלל


def tex_hull(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    xm, ym = X % 64, Y % 64
    rgb = np.array([0.6, 0.63, 0.68], F32) * (0.85 + 0.25 * n[..., None])
    h = np.clip((np.minimum(np.minimum(xm, 63 - xm), np.minimum(ym, 63 - ym)) - 1) / 2, 0, 1)
    ie = np.minimum(np.minimum(xm - 10, 53 - xm), np.minimum(ym - 8, 46 - ym))
    h = h - np.clip(ie / 2.5, 0, 1) * 0.6
    band = (ym >= 52) & (ym < 60)
    rgb = np.where(band[..., None], np.array([0.12, 0.25, 0.55], F32) * (0.9 + 0.2 * n[..., None]), rgb)
    rgb = rgb * emboss(h, 1.0)
    em = np.zeros((T, T, 3), F32)
    for cx, col in ((16, (0.2, 1.6, 2.0)), (24, (2.0, 0.3, 0.2)), (32, (0.3, 2.0, 0.6))):
        d = np.hypot(xm - cx, ym - 56)
        m = np.clip(1.8 - d, 0, 1)[..., None]
        em = em + m * np.array(col, F32)
    return rgb, em


def tex_window(rng):
    X, Y = grid_xy()
    e = np.minimum(np.minimum(X, TM - X), np.minimum(Y, TM - Y))
    inside = (e > 11) & (np.abs(X - 63.5) > 3)
    n = fbm(T, rng, 8, 4)
    frame = np.array([0.42, 0.44, 0.5], F32) * (0.8 + 0.3 * n[..., None])
    fh = np.clip((e - 2) / 4, 0, 1) - np.clip((e - 9) / 2, 0, 1) * 0.5
    frame = frame * emboss(fh + np.clip(4 - np.abs(X - 63.5), 0, 1), 1.0)
    stars = (rng.random((T, T)) > 0.988) * rng.uniform(0.6, 2.5, (T, T))
    neb = np.clip(fbm(T, rng, 4, 5) - 0.45, 0, 1) * 2
    space = (stars[..., None] * np.array([1.0, 1.0, 1.1], F32)
             + neb[..., None] * np.array([0.25, 0.08, 0.45], F32)
             + np.array([0.01, 0.01, 0.03], F32))
    pd = np.hypot(X - 90, Y - 84) / 30
    pnx, pny = (X - 90) / 30, (Y - 84) / 30
    pnz = np.sqrt(np.clip(1 - pd * pd, 0, 1))
    lit = np.clip(-pnx * 0.7 - pny * 0.3 + pnz * 0.6, 0, 1)
    bands = 0.7 + 0.3 * np.sin(Y * 0.45 + fbm(T, rng, 8, 3) * 6)
    planet = (lit * bands)[..., None] * np.array([0.35, 0.6, 1.1], F32)
    rim = np.clip(1 - np.abs(pd - 1) * 8, 0, 1)[..., None] * np.array([0.2, 0.5, 1.0], F32)
    space = np.where((pd < 1)[..., None], planet, space) + rim
    space = space + np.clip(1 - np.abs((X - Y) - 10) / 6, 0, 1)[..., None] * 0.04
    rgb = np.where(inside[..., None], np.array([0.02, 0.02, 0.03], F32), frame)
    em = np.where(inside[..., None], space, 0).astype(F32)
    return rgb, em


def tex_hive(rng):
    X, Y = grid_xy()
    pts = rng.uniform(0, T, (11, 2))
    ds = []
    for ox in (-T, 0, T):
        for oy in (-T, 0, T):
            for px, py in pts:
                ds.append(np.hypot(X - px - ox, Y - py - oy))
    ds = np.sort(np.stack(ds), axis=0)
    d1, d2 = ds[0], ds[1]
    n = fbm(T, rng, 4, 6)
    vein = np.clip(1 - (d2 - d1) / 3.5, 0, 1)
    rgb = np.array([0.3, 0.12, 0.34], F32) * (0.4 + 0.9 * n[..., None])
    rgb = rgb * emboss(np.clip(d1 / 20, 0, 1) + n * 0.5, 1.6)
    rgb = rgb * (1 - vein[..., None]) + vein[..., None] * np.array([0.9, 0.3, 0.9], F32)
    em = (vein ** 2)[..., None] * np.array([1.4, 0.2, 1.6], F32)
    return rgb, em


def tex_deck(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    xm, ym = X % 32, Y % 32
    h = np.clip((np.minimum(np.minimum(xm, 31 - xm), np.minimum(ym, 31 - ym)) - 1) / 2, 0, 1)
    tone = rng.uniform(0.8, 1.1, (4, 4))[(X // 32).astype(int), (Y // 32).astype(int)][..., None]
    rgb = np.array([0.22, 0.24, 0.28], F32) * tone * (0.7 + 0.5 * n[..., None]) * emboss(h, 1.0)
    line = (np.minimum(np.minimum(X, TM - X), np.minimum(Y, TM - Y)) < 1.5)
    em = np.where(line[..., None], np.array([0.1, 0.9, 1.4], F32), 0).astype(F32)
    rgb = np.where(line[..., None], np.array([0.3, 0.8, 1.0], F32), rgb)
    return rgb, em


def tex_grate(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 4)
    hole = ((X % 8) < 5) & ((Y % 8) < 5)
    rgb = np.array([0.32, 0.34, 0.38], F32) * (0.8 + 0.3 * n[..., None])
    rgb = rgb * emboss((~hole).astype(F32), 0.5)
    glow = (0.2 + 0.8 * n)[..., None] * np.array([0.05, 0.3, 0.6], F32)
    rgb = np.where(hole[..., None], np.array([0.02, 0.03, 0.05], F32), rgb)
    em = np.where(hole[..., None], glow, 0).astype(F32)
    return rgb, em


def tex_energy(rng):
    n = fbm(T, rng, 4, 6)
    n2 = fbm(T, rng, 8, 4)
    ridge = 1 - np.abs(2 * n - 1)
    ridge2 = 1 - np.abs(2 * n2 - 1)
    arc = np.clip(ridge ** 8 * 1.6 + ridge2 ** 10, 0, 1.5)[..., None]
    rgb = np.array([0.05, 0.15, 0.3], F32) + arc * 0.5
    em = np.array([0.05, 0.18, 0.45], F32) + arc * np.array([0.6, 1.6, 2.6], F32)
    return rgb, em


def tex_space_ceiling(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    xm, ym = X % 64, Y % 64
    h = np.clip((np.minimum(np.minimum(xm, 63 - xm), np.minimum(ym, 63 - ym)) - 2) / 3, 0, 1)
    rgb = np.array([0.45, 0.47, 0.52], F32) * (0.8 + 0.3 * n[..., None]) * emboss(h, 0.8)
    lamp = (np.abs(xm - 32) < 14) & (np.abs(ym - 32) < 5)
    rgb = np.where(lamp[..., None], np.array([0.9, 0.95, 1.0], F32), rgb)
    em = np.where(lamp[..., None], np.array([1.3, 1.5, 1.8], F32), 0).astype(F32)
    return rgb, em


# ---------------------------------------------------------------- טקסטורות ג'ונגל


def tex_foliage(rng):
    X, Y = grid_xy()
    rgb = np.zeros((T, T, 3), F32) + np.array([0.03, 0.08, 0.03], F32)
    for k in range(170):
        cx, cy = rng.uniform(0, T, 2)
        rx, ry = rng.uniform(7, 15), rng.uniform(3, 6)
        a = rng.uniform(0, math.pi)
        dx = (X - cx + T / 2) % T - T / 2
        dy = (Y - cy + T / 2) % T - T / 2
        uu = dx * math.cos(a) + dy * math.sin(a)
        vv = -dx * math.sin(a) + dy * math.cos(a)
        r2 = (uu / rx) ** 2 + (vv / ry) ** 2
        m = r2 < 1
        depth = 0.45 + 0.55 * k / 170
        g = rng.uniform(0.75, 1.2)
        col = np.array([0.16 * g, 0.42 * g, 0.12 * g + rng.uniform(0, 0.05)], F32) * depth
        shade = (0.55 + 0.5 * (1 - r2)) * np.where(np.abs(vv) < 0.6, 0.7, 1.0)
        rgb = np.where(m[..., None], col * shade[..., None], rgb)
    return rgb, np.zeros_like(rgb)


def tex_ruins(rng):
    X, Y = grid_xy()
    bh, bw = 32, 64
    row = (Y // bh).astype(int)
    xo = (X + (row % 2) * 32) % T
    lx, ly = xo % bw, Y % bh
    e = np.minimum(np.minimum(lx, bw - 1 - lx), np.minimum(ly, bh - 1 - ly))
    h = np.clip((e - 1.5) / 3, 0, 1)
    n = fbm(T, rng, 4, 6)
    glyph = (np.sin(lx * 0.35) * np.sin(ly * 0.5) > 0.55) & (row % 2 == 1) & (e > 5)
    h = h - glyph * 0.5
    tone = rng.uniform(0.8, 1.1, (4, 3))[row, (xo // bw).astype(int)][..., None]
    rgb = np.array([0.52, 0.5, 0.42], F32) * tone * (0.6 + 0.6 * n[..., None])
    rgb = np.where((h > 0)[..., None], rgb, rgb * 0.3) * emboss(h + n * 0.4, 1.1)
    moss = np.clip((fbm(T, rng, 4, 5) - 0.52) * 4 + (1 - ly / bh) * 0.3, 0, 1)[..., None]
    rgb = rgb * (1 - moss) + moss * np.array([0.18, 0.38, 0.1], F32) * (0.6 + 0.6 * n[..., None])
    return rgb, np.zeros_like(rgb)


def tex_cliff(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    band = np.sin(Y * 0.3 + n * 7)
    rgb = np.array([0.5, 0.4, 0.3], F32) * (0.7 + 0.25 * band[..., None] + 0.4 * n[..., None])
    rgb = rgb * emboss(band * 0.6 + n * 1.5, 1.0)
    for k in range(5):
        x0 = rng.uniform(0, T)
        vine = np.abs(((X - x0 - 4 * np.sin(Y * 0.15 + k)) + T / 2) % T - T / 2) < 1.8
        rgb = np.where(vine[..., None], np.array([0.15, 0.4, 0.1], F32) * (0.8 + 0.4 * n[..., None]), rgb)
    return rgb, np.zeros_like(rgb)


def tex_grass(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    blades = rng.random((T, T)).astype(F32)
    blades = (blades + np.roll(blades, 1, 1) + np.roll(blades, 2, 1)) / 3
    rgb = np.array([0.24, 0.48, 0.13], F32) * (0.55 + 0.5 * blades[..., None] + 0.3 * n[..., None])
    dry = np.clip((n - 0.6) * 3, 0, 1)[..., None]
    rgb = rgb * (1 - dry) + dry * np.array([0.5, 0.48, 0.2], F32)
    flowers = rng.random((T, T)) > 0.996
    rgb = np.where(flowers[..., None], np.array([0.95, 0.3, 0.5], F32), rgb)
    return rgb, np.zeros_like(rgb)


def tex_dirt(rng):
    n = fbm(T, rng, 4, 6)
    n2 = fbm(T, rng, 16, 3)
    peb = np.clip((n2 - 0.62) * 6, 0, 1)
    rgb = np.array([0.55, 0.42, 0.27], F32) * (0.6 + 0.6 * n[..., None])
    rgb = rgb * emboss(peb + n * 0.5, 1.2) + peb[..., None] * 0.08
    return rgb, np.zeros_like(rgb)


def tex_water(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 5)
    rip = np.sin((X + n * 30) * 0.25) * np.sin((Y + n * 25) * 0.2)
    rgb = np.array([0.08, 0.25, 0.28], F32) * (0.7 + 0.4 * n[..., None])
    em = np.clip(rip, 0, 1)[..., None] ** 4 * np.array([0.3, 0.45, 0.5], F32) + np.array([0.04, 0.09, 0.1], F32)
    return rgb, em


def tex_clouds(rng):
    n = fbm(T, rng, 4, 6)
    return np.repeat(n[..., None], 3, axis=2).astype(F32), np.zeros((T, T, 3), F32)


# ---------------------------------------------------------------- טקסטורות לשלבים 4-8


def blocks(rng, bw, bh, base, mortar, var=0.15, noise=0.6, gap=2, offset=True):
    X, Y = grid_xy()
    row = (Y // bh).astype(int)
    xo = (X + (row % 2) * (bw // 2 if offset else 0)) % T
    lx, ly = xo % bw, Y % bh
    e = np.minimum(np.minimum(lx, bw - 1 - lx), np.minimum(ly, bh - 1 - ly))
    h = np.clip((e - gap) / 3, 0, 1)
    n = fbm(T, rng, 4, 6)
    tone = rng.uniform(1 - var, 1 + var, (T // bh + 1, T // bw + 2))[row, (xo // bw).astype(int)][..., None]
    rgb = np.array(base, F32) * tone * (1 - noise / 2 + noise * n[..., None])
    rgb = np.where((h > 0)[..., None], rgb, np.array(mortar, F32) * (0.7 + 0.5 * n[..., None]))
    rgb = rgb * emboss(h + n * 0.4, 0.9)
    return rgb.astype(F32), n, X, Y, lx, ly


def Z3():
    return np.zeros((T, T, 3), F32)


def cracks(rng, scale=8, width=0.08):
    n2 = fbm(T, rng, scale, 5)
    return np.clip((1 - np.abs(2 * n2 - 1) - (1 - width)) / width, 0, 1)


# --- קרח
def tex_ice(rng):
    n = fbm(T, rng, 4, 6)
    cr = cracks(rng)[..., None]
    rgb = np.array([0.55, 0.76, 0.95], F32) * (0.6 + 0.5 * n[..., None]) * emboss(n * 1.5, 0.8)
    rgb = rgb * (1 - cr) + cr * 0.95
    em = np.array([0.05, 0.12, 0.2], F32) * (0.5 + n[..., None]) + cr * np.array([0.1, 0.2, 0.3], F32)
    return rgb, em


def tex_frost_concrete(rng):
    rgb, n, X, Y, lx, ly = blocks(rng, 64, 64, [0.5, 0.52, 0.56], [0.3, 0.3, 0.33], 0.08, 0.5, offset=False)
    frost = np.clip((44 - ly) / 44 * 0.9 + (n - 0.5) * 0.9, 0, 1)[..., None]
    rgb = rgb * (1 - frost) + frost * np.array([0.92, 0.95, 1.0], F32)
    lamp = (np.abs(X - 96) < 10) & (np.abs(Y - 90) < 4)
    return np.where(lamp[..., None], 1.0, rgb).astype(F32), np.where(lamp[..., None], np.array([1.5, 0.9, 0.4], F32), 0).astype(F32)


def tex_crates(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    base = np.where(((X // 64) % 2 == 0)[..., None], np.array([0.75, 0.33, 0.12], F32), np.array([0.14, 0.45, 0.5], F32))
    ribs = np.sin(X * 0.55) * 0.5 + 0.5
    xm = X % 64
    edge = np.clip((np.minimum(xm, 63 - xm) - 1) / 3, 0, 1)
    rgb = base * (0.7 + 0.35 * n[..., None]) * emboss(ribs * 0.5 + edge, 0.9)
    rust = np.clip((fbm(T, rng, 8, 4) - 0.6) * 4, 0, 1)[..., None]
    rgb = rgb * (1 - rust) + rust * np.array([0.35, 0.18, 0.08], F32)
    snow = np.clip((14 - Y) / 14 + (n - 0.5), 0, 1)[..., None]
    return rgb * (1 - snow) + snow * 0.95, Z3()


def tex_snow(rng):
    n = fbm(T, rng, 4, 6)
    rgb = np.array([0.86, 0.89, 0.96], F32) * (0.82 + 0.25 * n[..., None]) * emboss(n * 1.2, 0.6)
    sp = (rng.random((T, T)) > 0.994)[..., None]
    return rgb, (sp * 0.5).astype(F32) * np.ones(3, F32)


def tex_snowpath(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    tracks = (np.abs((X % 64) - 20) < 6) | (np.abs((X % 64) - 44) < 6)
    rgb = np.array([0.72, 0.74, 0.8], F32) * (0.8 + 0.3 * n[..., None])
    return np.where(tracks[..., None], rgb * 0.82, rgb) * emboss(tracks * 0.4 + n * 0.5, 0.6), Z3()


def tex_icefloor(rng):
    n = fbm(T, rng, 4, 5)
    cr = cracks(rng, 8, 0.06)[..., None]
    rgb = np.array([0.42, 0.62, 0.82], F32) * (0.8 + 0.3 * n[..., None])
    rgb = rgb * (1 - cr) + cr * 0.9
    em = np.array([0.1, 0.15, 0.24], F32) * (0.5 + n[..., None]) + cr * 0.15
    return rgb, em


# --- עיר בלילה
def tex_wetbrick(rng):
    rgb, n, X, Y, lx, ly = blocks(rng, 32, 16, [0.42, 0.2, 0.16], [0.12, 0.11, 0.11], 0.2, 0.6)
    streak = rng.random(T).astype(F32)[:, None] * np.ones((1, T), F32)
    rgb = rgb * (0.75 + 0.2 * streak[..., None])
    return rgb, (np.clip(streak - 0.85, 0, 1) * 0.4)[..., None] * np.array([0.3, 0.3, 0.5], F32)


def tex_shopwindow(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    glass = (X > 8) & (X < 119) & (Y > 10) & (Y < 96)
    rgb = np.array([0.18, 0.17, 0.2], F32) * (0.7 + 0.4 * n[..., None])
    rgb = np.where((Y >= 100)[..., None], np.array([0.3, 0.28, 0.3], F32) * (0.7 + 0.4 * n[..., None]), rgb)
    inside = np.array([0.15, 0.1, 0.25], F32) * (1.2 - Y[..., None] / 120)
    em = np.where(glass[..., None], inside, 0).astype(F32)
    ring = np.abs(np.hypot(X - 40, Y - 44) - 17) < 2.2
    bars = ((np.abs(Y - 36) < 2) | (np.abs(Y - 52) < 2)) & (X > 66) & (X < 108)
    tri = (Y > 66) & (Y < 84) & (np.abs(X - 86) < (Y - 66) * 0.9) & (np.abs(X - 86) > (Y - 66) * 0.9 - 3)
    em = np.where(ring[..., None], np.array([2.4, 0.4, 1.6], F32), em)
    em = np.where(bars[..., None], np.array([0.3, 1.9, 2.4], F32), em)
    em = np.where(tri[..., None], np.array([2.2, 1.8, 0.3], F32), em)
    rgb = np.where(glass[..., None], np.array([0.05, 0.05, 0.08], F32), rgb)
    return rgb, em.astype(F32)


def tex_shutter(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    h = np.sin(Y * 0.8) * 0.5 + 0.5
    rgb = np.array([0.42, 0.44, 0.48], F32) * (0.7 + 0.35 * n[..., None]) * emboss(h, 0.6)
    for k in range(3):
        m = np.clip((fbm(T, rng, 4, 4) - 0.62) * 6, 0, 1)[..., None]
        col = np.array([[0.9, 0.2, 0.5], [0.2, 0.8, 0.9], [0.95, 0.8, 0.2]][k], F32)
        rgb = rgb * (1 - m) + m * col * (0.6 + 0.3 * h[..., None])
    return rgb, Z3()


def tex_asphalt(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 16, 4)
    rgb = np.array([0.13, 0.13, 0.15], F32) * (0.7 + 0.6 * n[..., None])
    line = (np.abs(X - 64) < 2.5) & ((Y // 32) % 2 == 0)
    rgb = np.where(line[..., None], np.array([0.85, 0.7, 0.2], F32), rgb)
    return rgb, np.where(line[..., None], np.array([0.15, 0.12, 0.02], F32), 0).astype(F32)


def tex_sidewalk(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    e = np.minimum(np.minimum(X % 32, 31 - X % 32), np.minimum(Y % 32, 31 - Y % 32))
    h = np.clip((e - 1) / 2, 0, 1)
    rgb = np.array([0.4, 0.4, 0.43], F32) * (0.75 + 0.35 * n[..., None])
    return np.where((h > 0)[..., None], rgb, rgb * 0.4) * emboss(h, 0.6), Z3()


def tex_puddle(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 5)
    band = value_noise(T, 8, rng)
    rgb = np.array([0.04, 0.05, 0.07], F32) * np.ones((T, T, 3), F32)
    em = (np.clip(band - 0.55, 0, 1) * 3)[..., None] * np.array([1.0, 0.25, 0.8], F32) \
        + (np.clip(0.4 - band, 0, 1) * 3)[..., None] * np.array([0.2, 0.7, 1.0], F32)
    rip = np.clip(1 - np.abs(np.hypot((X % 64) - 32, (Y % 64) - 32) - 14) / 1.5, 0, 1)[..., None]
    return rgb, (em * (0.5 + 0.5 * n[..., None]) * 0.6 + rip * 0.15).astype(F32)


# --- מתחת לים
def tex_rust(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    xm, ym = X % 64, Y % 64
    h = np.clip((np.minimum(np.minimum(xm, 63 - xm), np.minimum(ym, 63 - ym)) - 1) / 3, 0, 1)
    for cx in (6, 58):
        for cy in (6, 58):
            h = h + np.clip(1 - np.hypot(xm - cx, ym - cy) / 3, 0, 1)
    rgb = np.array([0.38, 0.36, 0.34], F32) * (0.7 + 0.3 * n[..., None])
    rust = np.clip((fbm(T, rng, 4, 6) - 0.45) * 3 + (Y / T - 0.5), 0, 1)[..., None]
    rgb = rgb * (1 - rust) + rust * np.array([0.55, 0.28, 0.12], F32) * (0.6 + 0.6 * n[..., None])
    return rgb * emboss(h, 1.0), Z3()


def tex_seawindow(rng):
    X, Y = grid_xy()
    e = np.minimum(np.minimum(X, TM - X), np.minimum(Y, TM - Y))
    inside = e > 10
    n = fbm(T, rng, 4, 5)
    frame = np.array([0.35, 0.33, 0.3], F32) * (0.8 + 0.3 * n[..., None]) * emboss(np.clip((e - 2) / 4, 0, 1), 1.0)
    water = np.array([0.02, 0.12, 0.25], F32) * (1.6 - Y[..., None] / T) + n[..., None] * 0.04
    rays = np.clip(np.sin((X + Y * 0.4) * 0.12) * np.sin((X - Y * 0.2) * 0.05), 0, 1)[..., None] * 0.12
    water = water + rays * np.array([0.3, 0.8, 1.0], F32)
    for k in range(5):
        fx, fy = rng.uniform(20, 108), rng.uniform(20, 100)
        fish = ((X - fx) / 7) ** 2 + ((Y - fy) / 3) ** 2 < 1
        tail = (np.abs(Y - fy) < (X - fx - 5)) & (X - fx > 5) & (X - fx < 10)
        water = np.where((fish | tail)[..., None], np.array([0.15, 0.6, 0.7], F32), water)
    bub = np.zeros((T, T), bool)
    for k in range(10):
        bx, by = rng.uniform(15, 113), rng.uniform(15, 113)
        bub |= np.abs(np.hypot(X - bx, Y - by) - 2) < 0.8
    water = np.where(bub[..., None], np.array([0.5, 0.8, 0.9], F32), water)
    rgb = np.where(inside[..., None], np.array([0.02, 0.03, 0.05], F32), frame)
    return rgb, np.where(inside[..., None], water, 0).astype(F32)


def tex_coral(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 6)
    n2 = fbm(T, rng, 4, 5)
    bumps = np.sin(X * 0.6 + n * 8) * np.sin(Y * 0.6 + n * 6) * 0.5 + 0.5
    pal = np.stack([np.array([0.95, 0.4, 0.55], F32), np.array([1.0, 0.6, 0.2], F32), np.array([0.6, 0.3, 0.8], F32)])
    idx = np.clip((n2 * 3).astype(int), 0, 2)
    rgb = pal[idx] * (0.5 + 0.6 * bumps[..., None]) * emboss(bumps + n, 1.2)
    dots = (rng.random((T, T)) > 0.985)[..., None]
    return np.where(dots, np.array([1.0, 0.9, 0.6], F32), rgb).astype(F32), (dots * 0.3 * np.ones(3)).astype(F32)


def tex_seasand(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    rip = np.sin((X + n * 30) * 0.35) * 0.5 + 0.5
    rgb = np.array([0.6, 0.55, 0.42], F32) * (0.75 + 0.2 * rip[..., None] + 0.2 * n[..., None])
    shells = (rng.random((T, T)) > 0.993)[..., None]
    return np.where(shells, np.array([0.95, 0.85, 0.8], F32), rgb).astype(F32), Z3()


def tex_flood(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 5)
    rip = np.sin((X + n * 30) * 0.25) * np.sin((Y + n * 25) * 0.2)
    rgb = np.array([0.05, 0.2, 0.24], F32) * (0.7 + 0.4 * n[..., None])
    em = np.clip(rip, 0, 1)[..., None] ** 4 * np.array([0.2, 0.5, 0.55], F32) + np.array([0.02, 0.06, 0.08], F32)
    return rgb, em.astype(F32)


def tex_pipes(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    yy = (Y % 32) - 16
    pipe = np.abs(yy) < 11
    sh = np.sqrt(np.clip(1 - (yy / 11) ** 2, 0, 1))
    rgb = np.where(pipe[..., None], np.array([0.42, 0.4, 0.38], F32) * (0.3 + 0.8 * sh[..., None]),
                   np.array([0.08, 0.09, 0.1], F32))
    rings = pipe & ((X % 40) < 3)
    rgb = np.where(rings[..., None], rgb * 0.5, rgb) * (0.8 + 0.3 * n[..., None])
    return rgb.astype(F32), Z3()


# --- מדבר ופירמידה
def tex_sandstone(rng):
    rgb, n, X, Y, lx, ly = blocks(rng, 64, 32, [0.78, 0.62, 0.4], [0.5, 0.4, 0.27], 0.1, 0.5)
    return rgb, Z3()


def tex_painted(rng):
    rgb, n, X, Y, lx, ly = blocks(rng, 128, 128, [0.82, 0.7, 0.5], [0.6, 0.5, 0.35], 0.02, 0.4, gap=0)
    red, blue, gold = (np.array(c, F32) for c in ([0.7, 0.15, 0.1], [0.12, 0.3, 0.6], [0.9, 0.7, 0.2]))
    band = (Y < 14) | (Y > 113)
    tri = band & (((X % 16) - 8) ** 2 < ((np.where(Y < 14, Y, 127 - Y)) * 0.6) ** 2)
    rgb = np.where(band[..., None], gold * (0.7 + 0.3 * n[..., None]), rgb)
    rgb = np.where(tri[..., None], blue, rgb)
    for cx in (32, 96):     # סמלים מקוריים: עין-עיגול וקרניים
        d = np.hypot(X - cx, Y - 52)
        rgb = np.where((np.abs(d - 13) < 2.2)[..., None], red, rgb)
        rgb = np.where((d < 5)[..., None], blue, rgb)
        ang = np.arctan2(Y - 52, X - cx)
        rays = (d > 17) & (d < 26) & (np.abs(np.sin(ang * 6)) < 0.25)
        rgb = np.where(rays[..., None], gold, rgb)
    zig = np.abs((Y - 92) - 6 * np.abs(((X / 8) % 2) - 1) * 2) < 2
    rgb = np.where(zig[..., None], red, rgb)
    return rgb * (0.8 + 0.25 * n[..., None]), Z3()


def tex_dune(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    band = np.sin(Y * 0.25 + n * 6)
    rgb = np.array([0.72, 0.55, 0.36], F32) * (0.7 + 0.2 * band[..., None] + 0.3 * n[..., None])
    return rgb * emboss(band * 0.5 + n * 1.5, 1.0), Z3()


def tex_sand(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    rip = np.sin((X + n * 40) * 0.3) * 0.5 + 0.5
    rgb = np.array([0.86, 0.72, 0.5], F32) * (0.78 + 0.18 * rip[..., None] + 0.15 * n[..., None])
    return rgb * emboss(rip * 0.5, 0.6), Z3()


def tex_stonetile(rng):
    rgb, em = tex_stone_floor(rng)
    return (rgb * np.array([1.45, 1.2, 0.85], F32)).astype(F32), em


def tex_quicksand(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    a = np.arctan2(Y - 64, X - 64)
    d = np.hypot(X - 64, Y - 64)
    sw = np.sin(a * 3 + d * 0.25 + n * 4) * 0.5 + 0.5
    rgb = np.array([0.55, 0.42, 0.26], F32) * (0.55 + 0.35 * sw[..., None] + 0.2 * n[..., None])
    return rgb * emboss(sw, 0.8), Z3()


# --- עולם פיקסלים
def tex_neongrid(rng):
    X, Y = grid_xy()
    line = ((X % 16) < 1.5) | ((Y % 16) < 1.5)
    border = (np.minimum(np.minimum(X, TM - X), np.minimum(Y, TM - Y)) < 3)
    rgb = np.where((line | border)[..., None], np.array([0.4, 0.9, 1.0], F32), np.array([0.05, 0.03, 0.1], F32))
    em = np.where(line[..., None], np.array([0.2, 1.4, 2.0], F32), 0) + np.where(border[..., None], np.array([1.6, 0.3, 1.8], F32), 0)
    return rgb.astype(F32), em.astype(F32)


def tex_checker(rng):
    X, Y = grid_xy()
    chk = ((X // 32 + Y // 32) % 2 == 0)
    rgb = np.where(chk[..., None], np.array([0.85, 0.25, 0.65], F32), np.array([0.25, 0.1, 0.45], F32))
    e = np.minimum(np.minimum(X % 32, 31 - X % 32), np.minimum(Y % 32, 31 - Y % 32))
    edge = (e < 2)[..., None]
    rgb = rgb * emboss(np.clip(e / 3, 0, 1), 0.6)
    return rgb.astype(F32), np.where(edge, np.array([1.4, 0.4, 1.2], F32), 0).astype(F32)


def tex_glitchwall(rng):
    X, Y = grid_xy()
    pal = np.array([[0.1, 0.9, 1.0], [1.0, 0.2, 0.7], [1.0, 0.9, 0.2], [0.2, 0.1, 0.4], [0.05, 0.05, 0.1]], F32)
    cells = rng.integers(0, 5, (T // 8, T // 8))
    idx = cells[(X // 8).astype(int), (Y // 8).astype(int)]
    rgb = pal[idx]
    em = np.where((idx < 3)[..., None], rgb * 0.9, 0).astype(F32)
    return rgb.astype(F32), em


def tex_gridfloor(rng):
    X, Y = grid_xy()
    line = ((X % 32) < 1.5) | ((Y % 32) < 1.5)
    rgb = np.where(line[..., None], np.array([1.0, 0.4, 0.9], F32), np.array([0.08, 0.03, 0.14], F32))
    return rgb.astype(F32), np.where(line[..., None], np.array([2.0, 0.4, 1.8], F32), 0).astype(F32)


def tex_checkerfloor(rng):
    X, Y = grid_xy()
    chk = ((X // 32 + Y // 32) % 2 == 0)
    rgb = np.where(chk[..., None], np.array([0.75, 0.75, 0.85], F32), np.array([0.1, 0.08, 0.16], F32))
    return rgb.astype(F32), Z3()


def tex_static(rng):
    X, Y = grid_xy()
    v = rng.random((T // 4, T // 4))[(X // 4).astype(int), (Y // 4).astype(int)]
    col = np.stack([v, rng.random((T // 4, T // 4))[(X // 4).astype(int), (Y // 4).astype(int)], np.ones_like(v)], -1)
    rgb = (col * v[..., None]).astype(F32)
    return rgb, (rgb * np.array([1.6, 0.6, 1.8], F32)).astype(F32)


EXTRA_ATLAS = {
    "arctic": [tex_ice, tex_frost_concrete, tex_crates, tex_snow, tex_snowpath, tex_icefloor, tex_clouds],
    "city": [tex_wetbrick, tex_shopwindow, tex_shutter, tex_sidewalk, tex_asphalt, tex_puddle, tex_clouds],
    "ocean": [tex_rust, tex_seawindow, tex_coral, tex_deck, tex_seasand, tex_flood, tex_pipes],
    "desert": [tex_sandstone, tex_painted, tex_dune, tex_sand, tex_stonetile, tex_quicksand, tex_clouds],
    "pixel": [tex_neongrid, tex_checker, tex_glitchwall, tex_gridfloor, tex_checkerfloor, tex_static, tex_clouds],
}


# ---------------------------------------------------------------- טקסטורות לשלבים 9-12


# --- ממתקים
def tex_candycane(rng):
    X, Y = grid_xy()
    stripe = (((X + Y) // 16) % 2 == 0)
    rgb = np.where(stripe[..., None], np.array([0.9, 0.12, 0.15], F32), np.array([0.97, 0.95, 0.95], F32))
    gloss = (np.sin(X * math.pi / 32) * 0.5 + 0.5)
    rgb = rgb * (0.7 + 0.35 * gloss[..., None])
    return rgb.astype(F32), (np.clip(gloss - 0.85, 0, 1) * 2)[..., None] * np.ones(3, F32)


def tex_chocolate(rng):
    rgb, n, X, Y, lx, ly = blocks(rng, 32, 32, [0.38, 0.2, 0.1], [0.22, 0.11, 0.05], 0.05, 0.3, gap=2, offset=False)
    return rgb, Z3()


def tex_jelly(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 5)
    pal = np.array([[0.2, 0.9, 0.35], [1.0, 0.55, 0.1], [0.65, 0.25, 0.9], [0.95, 0.2, 0.45]], F32)
    col = pal[((X // 64) + 2 * (Y // 64)).astype(int) % 4]
    e = np.minimum(np.minimum(X % 64, 63 - X % 64), np.minimum(Y % 64, 63 - Y % 64))
    h = np.clip(e / 6, 0, 1)
    rgb = col * (0.55 + 0.4 * n[..., None]) * emboss(h, 0.8)
    bub = np.zeros((T, T), bool)
    for k in range(14):
        bx, by = rng.uniform(0, T, 2)
        bub |= np.hypot(X - bx, Y - by) < rng.uniform(1.5, 3.5)
    rgb = np.where(bub[..., None], rgb * 1.4 + 0.15, rgb)
    return rgb.astype(F32), (col * 0.35 * (0.6 + 0.5 * n[..., None])).astype(F32)


def tex_frosting(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    sw = np.sin((X + Y) * 0.15 + n * 8) * 0.5 + 0.5
    rgb = np.array([1.0, 0.72, 0.85], F32) * (0.8 + 0.2 * sw[..., None]) * emboss(sw * 0.6, 0.6)
    pal = np.array([[1, 0.2, 0.3], [0.2, 0.7, 1], [1, 0.9, 0.2], [0.3, 0.9, 0.4], [1, 1, 1]], F32)
    sp = rng.random((T, T)) > 0.985
    idx = rng.integers(0, 5, (T, T))
    rgb = np.where(sp[..., None], pal[idx], rgb)
    return rgb.astype(F32), Z3()


def tex_cookie(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    rgb = np.array([0.78, 0.58, 0.32], F32) * (0.8 + 0.3 * n[..., None])
    chips = np.zeros((T, T), bool)
    for k in range(18):
        cx, cy = rng.uniform(0, T, 2)
        dx = (X - cx + T / 2) % T - T / 2
        dy = (Y - cy + T / 2) % T - T / 2
        chips |= dx * dx + dy * dy < rng.uniform(6, 14)
    rgb = np.where(chips[..., None], np.array([0.22, 0.11, 0.05], F32), rgb)
    return rgb * emboss(chips * 0.6 + n * 0.5, 0.8), Z3()


def tex_syrup(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 5)
    rip = np.sin((X + n * 30) * 0.2) * np.sin((Y + n * 20) * 0.17)
    rgb = np.array([0.7, 0.35, 0.08], F32) * (0.7 + 0.4 * n[..., None])
    em = np.clip(rip, 0, 1)[..., None] ** 4 * np.array([0.5, 0.3, 0.1], F32) + np.array([0.12, 0.05, 0.01], F32)
    return rgb, em.astype(F32)


# --- טירה רדופה
def tex_castlestone(rng):
    rgb, n, X, Y, lx, ly = blocks(rng, 48, 32, [0.42, 0.42, 0.48], [0.18, 0.18, 0.2], 0.15, 0.6)
    moss = np.clip((fbm(T, rng, 4, 5) - 0.55) * 4, 0, 1)[..., None] * (Y[..., None] / T)
    return rgb * (1 - moss) + moss * np.array([0.15, 0.25, 0.12], F32), Z3()


def tex_woodpanel(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    plank = (X // 16).astype(int)
    tone = rng.uniform(0.8, 1.15, 8)[plank % 8][..., None]
    grain = np.sin(Y * 0.3 + n * 10 + plank) * 0.5 + 0.5
    rgb = np.array([0.38, 0.22, 0.12], F32) * tone * (0.7 + 0.3 * grain[..., None])
    rgb = np.where(((X % 16) < 1)[..., None], rgb * 0.4, rgb)
    fr = (X > 26) & (X < 102) & (Y > 18) & (Y < 82)
    inner = (X > 32) & (X < 96) & (Y > 24) & (Y < 76)
    gold = np.array([0.85, 0.65, 0.25], F32) * (0.7 + 0.4 * n[..., None])
    sky = np.array([0.15, 0.1, 0.3], F32) + (Y[..., None] - 24) / 52 * np.array([0.35, 0.15, 0.2], F32)
    hill = Y > 60 - 8 * np.sin(X * 0.1)
    moon = np.hypot(X - 78, Y - 38) < 6
    paint = np.where(hill[..., None], np.array([0.05, 0.1, 0.08], F32), sky)
    paint = np.where(moon[..., None], np.array([0.95, 0.9, 0.7], F32), paint)
    rgb = np.where(fr[..., None], gold, rgb)
    rgb = np.where(inner[..., None], paint * (0.85 + 0.2 * n[..., None]), rgb)
    return rgb.astype(F32), Z3()


def tex_irongate(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    bg = np.array([0.04, 0.03, 0.06], F32) * np.ones((T, T, 3), F32)
    xm = X % 21
    bar = np.abs(xm - 10) < 3.5
    cross = (np.abs(Y - 40) < 3) | (np.abs(Y - 100) < 3)
    sh = np.sqrt(np.clip(1 - ((xm - 10) / 3.5) ** 2, 0, 1))
    metal = np.array([0.32, 0.3, 0.3], F32) * (0.4 + 0.7 * sh[..., None]) * (0.8 + 0.3 * n[..., None])
    rgb = np.where((bar | cross)[..., None], metal, bg)
    spike = (Y < 10) & (np.abs(xm - 10) < (10 - Y) * 0.4)
    rgb = np.where(spike[..., None], metal, rgb)
    return rgb.astype(F32), np.where((bar | cross)[..., None], 0, np.array([0.06, 0.02, 0.1], F32)).astype(F32)


def tex_darkstone(rng):
    rgb, em = tex_stone_floor(rng)
    return (rgb * np.array([0.75, 0.75, 0.85], F32)).astype(F32), em


def tex_carpet(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 16, 3)
    rgb = np.array([0.55, 0.06, 0.08], F32) * (0.75 + 0.35 * n[..., None])
    xm = X % 64
    border = (np.abs(xm - 6) < 3) | (np.abs(xm - 57) < 3)
    diamond = (np.abs(xm - 32) + np.abs((Y % 32) - 16)) < 9
    rgb = np.where(border[..., None], np.array([0.85, 0.65, 0.2], F32), rgb)
    rgb = np.where(diamond[..., None], np.array([0.75, 0.55, 0.15], F32) * (0.8 + 0.2 * n[..., None]), rgb)
    return rgb.astype(F32), Z3()


def tex_cursed(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    bub = np.clip(1 - np.abs(np.hypot((X % 32) - 16, (Y % 32) - 16) - 6 - n * 6) / 2, 0, 1)
    rgb = np.array([0.05, 0.2, 0.05], F32) * (0.6 + 0.6 * n[..., None])
    em = (np.array([0.1, 0.6, 0.12], F32) * (0.4 + n[..., None]) + bub[..., None] * np.array([0.3, 1.2, 0.3], F32))
    return rgb, em.astype(F32)


# --- מאדים
def tex_redrock(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    band = np.sin(Y * 0.22 + n * 7)
    rgb = np.array([0.62, 0.28, 0.16], F32) * (0.65 + 0.2 * band[..., None] + 0.35 * n[..., None])
    return rgb * emboss(band * 0.6 + n * 1.6, 1.1), Z3()


def tex_habitat(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    xm = X % 64
    h = np.clip((np.minimum(xm, 63 - xm) - 1) / 3, 0, 1)
    rgb = np.array([0.82, 0.83, 0.85], F32) * (0.85 + 0.2 * n[..., None]) * emboss(h, 0.8)
    stripe = (Y > 96) & (Y < 106)
    rgb = np.where(stripe[..., None], np.array([0.8, 0.25, 0.1], F32), rgb)
    d = np.hypot(xm - 32, Y - 50)
    win = d < 15
    rim = (d >= 15) & (d < 19)
    rgb = np.where(rim[..., None], np.array([0.35, 0.36, 0.4], F32), rgb)
    rgb = np.where(win[..., None], np.array([0.1, 0.1, 0.12], F32), rgb)
    em = np.where(win[..., None], np.array([1.4, 1.0, 0.5], F32) * (0.6 + 0.4 * (1 - d[..., None] / 15)), 0)
    return rgb.astype(F32), em.astype(F32)


def tex_wreck(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    xm, ym = X % 64, Y % 48
    h = np.clip((np.minimum(np.minimum(xm, 63 - xm), np.minimum(ym, 47 - ym)) - 1) / 3, 0, 1)
    rgb = np.array([0.35, 0.36, 0.38], F32) * (0.7 + 0.35 * n[..., None]) * emboss(h, 1.0)
    burn = np.clip((fbm(T, rng, 4, 5) - 0.5) * 3, 0, 1)[..., None]
    rgb = rgb * (1 - burn * 0.8)
    em = (np.clip(burn - 0.85, 0, 1) * 4) * np.array([1.2, 0.4, 0.1], F32)
    return rgb.astype(F32), em.astype(F32)


def tex_reddust(rng):
    n = fbm(T, rng, 4, 6)
    n2 = fbm(T, rng, 16, 3)
    rocks = np.clip((n2 - 0.65) * 5, 0, 1)
    rgb = np.array([0.72, 0.36, 0.2], F32) * (0.7 + 0.4 * n[..., None])
    return rgb * emboss(rocks + n * 0.5, 1.0), Z3()


def tex_toxic(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    d = np.hypot((X % 64) - 32, (Y % 64) - 32) / 32
    rgb = np.array([0.2, 0.35, 0.1], F32) * (0.6 + 0.5 * n[..., None])
    em = np.clip(1 - d, 0, 1)[..., None] ** 1.5 * np.array([0.5, 1.6, 0.3], F32) * (0.6 + 0.6 * n[..., None])
    return rgb, (em + np.array([0.05, 0.15, 0.03], F32)).astype(F32)


# --- יער פטריות
def tex_mushstem(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    fib = rng.random(T).astype(F32)[:, None]
    rgb = np.array([0.75, 0.7, 0.58], F32) * (0.7 + 0.25 * fib[..., None] + 0.2 * n[..., None])
    rgb = rgb * emboss(np.sin(X * 0.4) * 0.3 + n, 0.8)
    em = Z3()
    for k in range(9):
        cx, cy = rng.uniform(0, T, 2)
        dx = (X - cx + T / 2) % T - T / 2
        dy = (Y - cy + T / 2) % T - T / 2
        m = np.clip(1 - np.hypot(dx, dy) / rng.uniform(3, 6), 0, 1)[..., None]
        em = em + m * np.array([0.2, 1.2, 1.4], F32)
        rgb = rgb * (1 - m) + m * np.array([0.4, 0.9, 1.0], F32)
    return rgb.astype(F32), em.astype(F32)


def tex_crystalrock(rng):
    X, Y = grid_xy()
    pts = rng.uniform(0, T, (12, 2))
    ds = []
    for ox in (-T, 0, T):
        for oy in (-T, 0, T):
            for px, py in pts:
                ds.append(np.hypot(X - px - ox, Y - py - oy))
    ds = np.sort(np.stack(ds), axis=0)
    edge = np.clip(1 - (ds[1] - ds[0]) / 2.5, 0, 1)
    n = fbm(T, rng, 4, 5)
    facet = np.clip(ds[0] / 22, 0, 1)
    rgb = np.array([0.2, 0.14, 0.3], F32) * (0.5 + 0.6 * facet[..., None]) * (0.8 + 0.3 * n[..., None])
    em = edge[..., None] * np.array([0.9, 0.4, 1.6], F32) + (1 - facet[..., None]) * np.array([0.15, 0.05, 0.25], F32)
    return rgb.astype(F32), em.astype(F32)


def tex_hedge(rng):
    rgb, em = tex_foliage(rng)
    rgb = rgb * np.array([0.35, 0.55, 0.75], F32)
    X, Y = grid_xy()
    berries = rng.random((T, T)) > 0.992
    em = np.where(berries[..., None], np.array([1.6, 0.4, 1.2], F32), 0).astype(F32)
    return rgb.astype(F32), em


def tex_moss(rng):
    n = fbm(T, rng, 4, 6)
    n2 = fbm(T, rng, 16, 3)
    rgb = np.array([0.12, 0.25, 0.14], F32) * (0.6 + 0.6 * n[..., None]) * emboss(n2, 0.8)
    specks = (rng.random((T, T)) > 0.995)[..., None]
    return rgb.astype(F32), (specks * np.array([0.3, 1.2, 1.0], F32)).astype(F32)


def tex_glowpath(rng):
    rgb, em = tex_stone_floor(rng)
    X, Y = grid_xy()
    line = ((X % 64) < 2) | ((Y % 64) < 2)
    rgb = rgb * np.array([0.6, 0.7, 0.8], F32)
    em = np.where(line[..., None], np.array([0.2, 1.1, 1.4], F32), 0)
    return rgb.astype(F32), em.astype(F32)


def tex_sporepool(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    n2 = fbm(T, rng, 8, 4)
    rgb = np.array([0.25, 0.08, 0.3], F32) * (0.6 + 0.6 * n[..., None])
    em = np.clip(n2 - 0.3, 0, 1)[..., None] * np.array([1.4, 0.4, 1.8], F32)
    return rgb, em.astype(F32)


EXTRA_ATLAS.update({
    "candy": [tex_candycane, tex_chocolate, tex_jelly, tex_frosting, tex_cookie, tex_syrup, tex_clouds],
    "castle": [tex_castlestone, tex_woodpanel, tex_irongate, tex_darkstone, tex_carpet, tex_cursed, tex_clouds],
    "mars": [tex_redrock, tex_habitat, tex_wreck, tex_reddust, tex_metal_floor, tex_toxic, tex_clouds],
    "shroom": [tex_mushstem, tex_crystalrock, tex_hedge, tex_moss, tex_glowpath, tex_sporepool, tex_clouds],
})


# ---------------------------------------------------------------- טקסטורות לשלבים 13-16


# --- ממלכת השמיים
def tex_marble(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 6)
    vein = np.clip(1 - np.abs(np.sin((X + Y * 0.6) * 0.05 + n * 9)) * 6, 0, 1)
    rgb = np.array([0.93, 0.92, 0.9], F32) * (0.85 + 0.15 * n[..., None])
    rgb = rgb * (1 - vein[..., None] * 0.35) + vein[..., None] * np.array([0.1, 0.1, 0.15], F32) * 0.35
    e = np.minimum(np.minimum(X % 64, 63 - X % 64), np.minimum(Y % 64, 63 - Y % 64))
    return (rgb * emboss(np.clip(e / 3, 0, 1), 0.6)).astype(F32), Z3()


def tex_goldpillar(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    xm = X % 32
    flute = np.sin(xm * math.pi / 8) * 0.5 + 0.5
    rgb = np.array([0.95, 0.93, 0.88], F32) * (0.7 + 0.3 * flute[..., None]) * (0.9 + 0.1 * n[..., None])
    band = (Y < 12) | (Y > 115)
    gold = np.array([0.95, 0.75, 0.25], F32) * (0.7 + 0.4 * flute[..., None])
    rgb = np.where(band[..., None], gold, rgb)
    return rgb.astype(F32), np.where(band[..., None], np.array([0.15, 0.1, 0.02], F32), 0).astype(F32)


def tex_cloudwall(rng):
    n = fbm(T, rng, 4, 6)
    rgb = np.array([0.92, 0.94, 1.0], F32) * (0.75 + 0.3 * n[..., None]) * emboss(n * 2, 0.8)
    return rgb.astype(F32), (np.array([0.15, 0.16, 0.2], F32) * n[..., None]).astype(F32)


def tex_cloudfloor(rng):
    n = fbm(T, rng, 4, 6)
    rgb = np.array([0.95, 0.96, 1.0], F32) * (0.78 + 0.25 * n[..., None]) * emboss(n * 1.5, 0.6)
    return rgb.astype(F32), (np.array([0.12, 0.12, 0.16], F32) * n[..., None]).astype(F32)


def tex_marblepath(rng):
    rgb, em = tex_marble(rng)
    X, Y = grid_xy()
    line = ((X % 64) < 2) | ((Y % 64) < 2)
    return np.where(line[..., None], np.array([0.9, 0.72, 0.25], F32), rgb).astype(F32), em


def tex_stormcloud(rng):
    n = fbm(T, rng, 4, 6)
    n2 = fbm(T, rng, 8, 4)
    arc = np.clip((1 - np.abs(2 * n2 - 1)) ** 10 * 2, 0, 1.5)[..., None]
    rgb = np.array([0.3, 0.32, 0.42], F32) * (0.6 + 0.5 * n[..., None])
    em = arc * np.array([1.0, 1.2, 2.2], F32) + np.array([0.04, 0.05, 0.1], F32)
    return rgb.astype(F32), em.astype(F32)


# --- חדר צעצועים
def tex_wallpaper(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    stripe = ((X // 16) % 2 == 0)
    rgb = np.where(stripe[..., None], np.array([0.55, 0.75, 0.9], F32), np.array([0.75, 0.88, 0.95], F32))
    for cx, cy in ((24, 24), (88, 72), (56, 112)):
        star = (np.abs(X - cx) + np.abs(Y - cy)) < 6 + 3 * np.abs(np.sin(np.arctan2(Y - cy, X - cx) * 2.5))
        rgb = np.where(star[..., None], np.array([1.0, 0.85, 0.3], F32), rgb)
    skirting = Y > 112
    rgb = np.where(skirting[..., None], np.array([0.9, 0.88, 0.85], F32), rgb)
    return (rgb * (0.9 + 0.1 * n[..., None])).astype(F32), Z3()


def tex_toyblocks(rng):
    X, Y = grid_xy()
    pal = np.array([[0.9, 0.2, 0.2], [0.2, 0.5, 0.95], [0.98, 0.8, 0.15], [0.25, 0.75, 0.3]], F32)
    idx = ((X // 64) + 2 * (Y // 64)).astype(int) % 4
    xm, ym = X % 64, Y % 64
    e = np.minimum(np.minimum(xm, 63 - xm), np.minimum(ym, 63 - ym))
    h = np.clip(e / 5, 0, 1)
    rgb = pal[idx] * emboss(h, 1.0)
    d = np.hypot(xm - 32, ym - 32)
    shape = np.where(idx % 2 == 0, d < 14, (np.abs(xm - 32) < 12) & (np.abs(ym - 32) < 12))
    rgb = np.where(shape[..., None], np.array([0.97, 0.95, 0.9], F32), rgb)
    return rgb.astype(F32), Z3()


def tex_bookshelf(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    shelf = (Y % 64) > 56
    wood = np.array([0.45, 0.28, 0.14], F32) * (0.8 + 0.3 * n[..., None])
    rgb = wood.copy()
    x = 2
    while x < T - 4:
        w = int(rng.integers(6, 13))
        hgt = int(rng.integers(36, 54))
        col = np.array(rng.uniform(0.15, 0.85, 3), F32)
        for top in (0, 64):
            m = (X >= x) & (X < x + w) & ((Y % 64) >= 56 - hgt) & ((Y % 64) < 56) & (Y >= top) & (Y < top + 64)
            rgb = np.where(m[..., None], col * (0.8 + 0.3 * np.sin((X - x) / w * math.pi)[..., None]), rgb)
        x += w + 1
    rgb = np.where(shelf[..., None], wood * 1.1, rgb)
    return rgb.astype(F32), Z3()


def tex_woodfloor(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    plank = (Y // 16).astype(int)
    off = (plank * 37) % 64
    tone = rng.uniform(0.85, 1.1, 8)[plank % 8][..., None]
    grain = np.sin(X * 0.2 + n * 8 + plank) * 0.5 + 0.5
    rgb = np.array([0.62, 0.42, 0.24], F32) * tone * (0.75 + 0.25 * grain[..., None])
    gap = ((Y % 16) < 1) | (((X + off) % 64) < 1)
    return np.where(gap[..., None], rgb * 0.45, rgb).astype(F32), Z3()


def tex_rug(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 16, 3)
    d = np.maximum(np.abs(X - 64), np.abs(Y - 64))
    ring = (d // 10).astype(int) % 3
    pal = np.array([[0.75, 0.2, 0.3], [0.95, 0.75, 0.3], [0.2, 0.45, 0.7]], F32)
    return (pal[ring] * (0.75 + 0.3 * n[..., None])).astype(F32), Z3()


def tex_marblesfloor(rng):
    rgb, _ = tex_woodfloor(rng)
    X, Y = grid_xy()
    em = Z3()
    pal = np.array([[0.3, 0.6, 1.0], [1.0, 0.3, 0.4], [0.3, 1.0, 0.5], [1.0, 0.85, 0.2]], F32)
    for k in range(22):
        cx, cy = rng.uniform(0, T, 2)
        dx = (X - cx + T / 2) % T - T / 2
        dy = (Y - cy + T / 2) % T - T / 2
        r = rng.uniform(4, 7)
        d = np.hypot(dx, dy) / r
        m = d < 1
        sh = np.sqrt(np.clip(1 - d * d, 0, 1))
        col = pal[k % 4]
        rgb = np.where(m[..., None], col * (0.4 + 0.7 * sh[..., None]), rgb)
        em = np.where(m[..., None], col * 0.25 * sh[..., None], em)
    return rgb.astype(F32), em.astype(F32)


# --- מפעל
def tex_machinery(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    xm, ym = X % 64, Y % 64
    h = np.clip((np.minimum(np.minimum(xm, 63 - xm), np.minimum(ym, 63 - ym)) - 1) / 3, 0, 1)
    rgb = np.array([0.4, 0.42, 0.45], F32) * (0.7 + 0.35 * n[..., None]) * emboss(h, 1.0)
    d = np.hypot(xm - 32, ym - 26)
    gauge = d < 11
    needle = gauge & (np.abs((xm - 32) * 0.7 + (ym - 26) * 0.7) < 1.2) & (ym < 26)
    rgb = np.where((np.abs(d - 11) < 1.5)[..., None], np.array([0.75, 0.75, 0.78], F32), rgb)
    rgb = np.where(gauge[..., None], np.array([0.95, 0.93, 0.85], F32), rgb)
    rgb = np.where(needle[..., None], np.array([0.8, 0.1, 0.1], F32), rgb)
    led = np.hypot(xm - 50, ym - 50) < 3
    rgb = np.where(led[..., None], 1.0, rgb)
    em = np.where(led[..., None], np.array([0.3, 2.0, 0.4], F32), 0)
    return rgb.astype(F32), em.astype(F32)


def tex_hazardwall(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    stripe = (((X + Y) // 16) % 2 == 0)
    band = (Y > 40) & (Y < 88)
    rgb = np.array([0.35, 0.36, 0.38], F32) * (0.7 + 0.35 * n[..., None])
    rgb = np.where((band & stripe)[..., None], np.array([0.95, 0.75, 0.1], F32) * (0.8 + 0.2 * n[..., None]), rgb)
    rgb = np.where((band & ~stripe)[..., None], np.array([0.08, 0.08, 0.08], F32), rgb)
    wear = np.clip((fbm(T, rng, 8, 4) - 0.65) * 4, 0, 1)[..., None]
    return (rgb * (1 - wear * 0.6)).astype(F32), Z3()


def tex_pipewall(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    xm = (X % 32) - 16
    pipe = np.abs(xm) < 12
    sh = np.sqrt(np.clip(1 - (xm / 12) ** 2, 0, 1))
    col = np.where(((X // 32) % 2 == 0)[..., None], np.array([0.6, 0.3, 0.18], F32), np.array([0.3, 0.45, 0.35], F32))
    rgb = np.where(pipe[..., None], col * (0.3 + 0.8 * sh[..., None]), np.array([0.06, 0.06, 0.07], F32))
    rings = pipe & ((Y % 40) < 4)
    rgb = np.where(rings[..., None], rgb * 0.55, rgb) * (0.85 + 0.25 * n[..., None])
    return rgb.astype(F32), Z3()


def tex_concrete(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 6)
    rgb = np.array([0.45, 0.45, 0.44], F32) * (0.7 + 0.4 * n[..., None])
    line = (np.abs(X - 6) < 2.5) | (np.abs(X - 121) < 2.5)
    rgb = np.where(line[..., None], np.array([0.85, 0.7, 0.15], F32), rgb)
    oil = np.clip((fbm(T, rng, 4, 4) - 0.65) * 4, 0, 1)[..., None]
    return (rgb * (1 - oil * 0.6)).astype(F32), Z3()


def tex_conveyor(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 3)
    slat = (X % 16) < 13
    rgb = np.where(slat[..., None], np.array([0.18, 0.18, 0.2], F32), np.array([0.05, 0.05, 0.06], F32))
    arrow = (np.abs((X % 32) - 16 - np.abs(Y % 64 - 32) * 0.4) < 3) & (np.abs((Y % 64) - 32) < 14)
    rgb = np.where(arrow[..., None], np.array([0.95, 0.75, 0.1], F32), rgb)
    em = np.where(arrow[..., None], np.array([0.4, 0.3, 0.02], F32), 0)
    return (rgb * (0.85 + 0.25 * n[..., None])).astype(F32), em.astype(F32)


def tex_factoryceiling(rng):
    rgb, em = tex_pipes(rng)
    X, Y = grid_xy()
    lamp = (np.abs(X - 64) < 30) & (np.abs(Y - 64) < 4)
    rgb = np.where(lamp[..., None], 1.0, rgb)
    em = np.where(lamp[..., None], np.array([1.3, 1.25, 1.1], F32), em)
    return rgb.astype(F32), em.astype(F32)


# --- מקדש הדובדבן
def tex_redlattice(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    red = np.array([0.72, 0.12, 0.08], F32) * (0.8 + 0.3 * n[..., None])
    grid = ((X % 16) < 3) | ((Y % 16) < 3)
    frame = (np.minimum(np.minimum(X, TM - X), np.minimum(Y, TM - Y)) < 8)
    paper = np.array([0.95, 0.9, 0.8], F32) * (0.85 + 0.15 * n[..., None])
    rgb = np.where((grid | frame)[..., None], red, paper)
    em = np.where((grid | frame)[..., None], 0, np.array([0.35, 0.25, 0.12], F32))
    return rgb.astype(F32), em.astype(F32)


def tex_plaster(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 5)
    rgb = np.array([0.92, 0.9, 0.85], F32) * (0.85 + 0.15 * n[..., None])
    beam = ((X % 64) < 8) | (Y < 10) | ((Y > 60) & (Y < 68))
    wood = np.array([0.22, 0.13, 0.08], F32) * (0.8 + 0.3 * n[..., None])
    base = Y > 108
    stone = np.array([0.45, 0.43, 0.4], F32) * (0.7 + 0.4 * n[..., None])
    rgb = np.where(beam[..., None], wood, rgb)
    return np.where(base[..., None], stone, rgb).astype(F32), Z3()


def tex_bamboo(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 8, 4)
    rgb = np.array([0.08, 0.15, 0.06], F32) * np.ones((T, T, 3), F32)
    for k in range(9):
        cx = rng.uniform(0, T)
        r = rng.uniform(4, 7)
        dx = (X - cx + T / 2) % T - T / 2
        m = np.abs(dx) < r
        sh = np.sqrt(np.clip(1 - (dx / r) ** 2, 0, 1))
        node = (np.abs((Y + k * 17) % 40 - 20) < 1.5)
        col = np.array([0.45, 0.65, 0.2], F32) * (0.3 + 0.8 * sh[..., None])
        col = np.where(node[..., None], col * 0.6, col)
        rgb = np.where(m[..., None], col, rgb)
    return (rgb * (0.85 + 0.25 * n[..., None])).astype(F32), Z3()


def tex_gravel(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 16, 3)
    rake = np.sin(Y * 0.5 + np.sin(X * 0.05) * 3) * 0.5 + 0.5
    rgb = np.array([0.78, 0.75, 0.7], F32) * (0.75 + 0.15 * rake[..., None] + 0.2 * n[..., None])
    return (rgb * emboss(rake * 0.6, 0.6)).astype(F32), Z3()


def tex_deckwood(rng):
    rgb, em = tex_woodfloor(rng)
    return (rgb * np.array([0.8, 0.7, 0.65], F32)).astype(F32), em


def tex_koipond(rng):
    X, Y = grid_xy()
    n = fbm(T, rng, 4, 5)
    rgb = np.array([0.08, 0.2, 0.25], F32) * (0.7 + 0.4 * n[..., None])
    em = (np.clip(np.sin((X + n * 30) * 0.25) * np.sin((Y + n * 25) * 0.2), 0, 1) ** 4)[..., None] \
        * np.array([0.25, 0.4, 0.45], F32) + np.array([0.03, 0.07, 0.08], F32)
    for k in range(4):
        fx, fy = rng.uniform(20, 108, 2)
        a = rng.uniform(0, math.pi)
        u = (X - fx) * math.cos(a) + (Y - fy) * math.sin(a)
        v = -(X - fx) * math.sin(a) + (Y - fy) * math.cos(a)
        fish = (u / 9) ** 2 + (v / 3.5) ** 2 < 1
        col = np.array([1.0, 0.45, 0.1], F32) if k % 2 else np.array([1.0, 0.95, 0.9], F32)
        rgb = np.where(fish[..., None], col * 0.6, rgb)
        em = np.where(fish[..., None], col * 0.25, em)
    pad = np.zeros((T, T), bool)
    for k in range(3):
        px, py = rng.uniform(15, 113, 2)
        pad |= np.hypot(X - px, Y - py) < 9
    rgb = np.where(pad[..., None], np.array([0.2, 0.55, 0.2], F32), rgb)
    return rgb.astype(F32), em.astype(F32)


EXTRA_ATLAS.update({
    "skyland": [tex_marble, tex_goldpillar, tex_cloudwall, tex_cloudfloor, tex_marblepath, tex_stormcloud, tex_clouds],
    "toyroom": [tex_wallpaper, tex_toyblocks, tex_bookshelf, tex_woodfloor, tex_rug, tex_marblesfloor, tex_ceiling],
    "factory": [tex_machinery, tex_hazardwall, tex_pipewall, tex_concrete, tex_metal_floor, tex_conveyor, tex_factoryceiling],
    "temple": [tex_redlattice, tex_plaster, tex_bamboo, tex_gravel, tex_deckwood, tex_koipond, tex_clouds],
})


LAVA_IDX = 5
CEIL_IDX = 6


def build_atlas(theme="hell"):
    rng = np.random.default_rng(1337)
    if theme in EXTRA_ATLAS:
        surfs = [f(rng) for f in EXTRA_ATLAS[theme]]
    elif theme == "jungle":
        surfs = [tex_foliage(rng), tex_ruins(rng), tex_cliff(rng),
                 tex_grass(rng), tex_dirt(rng), tex_water(rng), tex_clouds(rng)]
    elif theme == "space":
        surfs = [tex_hull(rng), tex_window(rng), tex_hive(rng),
                 tex_deck(rng), tex_grate(rng), tex_energy(rng), tex_space_ceiling(rng)]
    else:
        surfs = [tex_brick(rng), tex_tech(rng), tex_rock(rng),
                 tex_stone_floor(rng), tex_metal_floor(rng), tex_lava(rng), tex_ceiling(rng)]
    atlas = np.stack([np.concatenate([np.clip(r, 0, 4), e], axis=2) for r, e in surfs]).astype(F32)
    return atlas


# ======================================================================= ספרייטים מוצללים

LX, LY, LZ = (np.array([-0.45, -0.55, 0.7]) / np.linalg.norm([-0.45, -0.55, 0.7])).tolist()


class Canvas:
    """קנבס לציור צורות מוצללות בתלת-ממד (אליפסואידים, צינורות, קופסאות)."""

    def __init__(self, w, h):
        self.w, self.h = w, h
        self.rgb = np.zeros((w, h, 3), F32)
        self.a = np.zeros((w, h), F32)
        self.e = np.zeros((w, h, 3), F32)
        self.X, self.Y = np.meshgrid(np.arange(w, dtype=F32) + 0.5,
                                     np.arange(h, dtype=F32) + 0.5, indexing="ij")

    def _box(self, cx, cy, rx, ry):
        x0, x1 = max(0, int(cx - rx - 1)), min(self.w, int(cx + rx + 2))
        y0, y1 = max(0, int(cy - ry - 1)), min(self.h, int(cy + ry + 2))
        return x0, x1, y0, y1

    def _paint(self, x0, x1, y0, y1, c, aa, emi):
        sl = (slice(x0, x1), slice(y0, y1))
        a3 = aa[..., None]
        self.rgb[sl] = self.rgb[sl] * (1 - a3) + c * a3
        self.e[sl] = self.e[sl] * (1 - a3) + emi * a3
        self.a[sl] = np.maximum(self.a[sl], aa)

    def ellipsoid(self, cx, cy, rx, ry, color, emissive=0.0, spec=0.25, shine=16.0):
        x0, x1, y0, y1 = self._box(cx, cy, rx, ry)
        if x0 >= x1 or y0 >= y1:
            return
        nx = (self.X[x0:x1, y0:y1] - cx) / rx
        ny = (self.Y[x0:x1, y0:y1] - cy) / ry
        r2 = nx * nx + ny * ny
        aa = np.clip((1 - np.sqrt(r2)) * min(rx, ry), 0, 1)
        if not (aa > 0).any():
            return
        nz = np.sqrt(np.clip(1 - r2, 0, 1))
        ndl = np.clip(nx * LX + ny * LY + nz * LZ, 0, 1)
        col = np.asarray(color, F32)
        c = col * (0.22 + 0.95 * ndl)[..., None] + (spec * ndl ** shine)[..., None]
        self._paint(x0, x1, y0, y1, c, aa, col * emissive)

    def rbox(self, cx, cy, rx, ry, color, p=8, spec=0.2, emissive=0.0):
        x0, x1, y0, y1 = self._box(cx, cy, rx, ry)
        nx = (self.X[x0:x1, y0:y1] - cx) / rx
        ny = (self.Y[x0:x1, y0:y1] - cy) / ry
        r = (np.abs(nx) ** p + np.abs(ny) ** p) ** (1 / p)
        aa = np.clip((1 - r) * min(rx, ry), 0, 1)
        s = r ** p * 2.5
        gx = np.sign(nx) * np.abs(nx) ** (p - 1) * s
        gy = np.sign(ny) * np.abs(ny) ** (p - 1) * s
        ln = np.sqrt(gx * gx + gy * gy + 1)
        ndl = np.clip((gx * LX + gy * LY + LZ) / ln, 0, 1)
        col = np.asarray(color, F32)
        c = col * (0.22 + 0.95 * ndl)[..., None] + (spec * ndl ** 12)[..., None]
        self._paint(x0, x1, y0, y1, c, aa, col * emissive)

    def capsule(self, x0, y0, x1, y1, r0, r1, color, emissive=0.0, spec=0.25, shine=16.0):
        """צינור מחודד עם הצללה חלקה (גליל + קצוות כדוריים)."""
        rm = max(r0, r1)
        bx0, bx1 = max(0, int(min(x0, x1) - rm - 1)), min(self.w, int(max(x0, x1) + rm + 2))
        by0, by1 = max(0, int(min(y0, y1) - rm - 1)), min(self.h, int(max(y0, y1) + rm + 2))
        if bx0 >= bx1 or by0 >= by1:
            return
        X, Y = self.X[bx0:bx1, by0:by1], self.Y[bx0:bx1, by0:by1]
        dx, dy = x1 - x0, y1 - y0
        L2 = dx * dx + dy * dy or 1e-6
        t = np.clip(((X - x0) * dx + (Y - y0) * dy) / L2, 0, 1)
        vx, vy = X - (x0 + dx * t), Y - (y0 + dy * t)
        r = r0 + (r1 - r0) * t
        nx, ny = vx / r, vy / r
        n2 = nx * nx + ny * ny
        aa = np.clip((1 - np.sqrt(n2)) * r, 0, 1)
        if not (aa > 0).any():
            return
        nz = np.sqrt(np.clip(1 - n2, 0, 1))
        ndl = np.clip(nx * LX + ny * LY + nz * LZ, 0, 1)
        col = np.asarray(color, F32)
        c = col * (0.22 + 0.95 * ndl)[..., None] + (spec * ndl ** shine)[..., None]
        self._paint(bx0, bx1, by0, by1, c, aa, col * emissive)

    def glow(self, cx, cy, r, color, power=2.0, alpha=True):
        x0, x1, y0, y1 = self._box(cx, cy, r, r)
        d = np.hypot(self.X[x0:x1, y0:y1] - cx, self.Y[x0:x1, y0:y1] - cy) / r
        g = np.clip(1 - d, 0, 1) ** power
        sl = (slice(x0, x1), slice(y0, y1))
        self.e[sl] += g[..., None] * np.asarray(color, F32)
        if alpha:
            self.a[sl] = np.maximum(self.a[sl], np.clip(g * 2, 0, 1))

    def sprite(self):
        return Sprite(self.rgb, self.a, self.e)

    def surface(self, gain=1.0):
        rgb = 1 - np.exp(-(self.rgb + self.e) * 1.3 * gain)
        s = pygame.Surface((self.w, self.h), pygame.SRCALPHA)
        px = pygame.surfarray.pixels3d(s)
        px[:] = (np.clip(rgb, 0, 1) * 255).astype(np.uint8)
        del px
        pa = pygame.surfarray.pixels_alpha(s)
        pa[:] = (np.clip(self.a, 0, 1) * 255).astype(np.uint8)
        del pa
        return s


class Sprite:
    def __init__(self, rgb, a, e):
        self.rgb, self.a, self.e = rgb.astype(F32), a.astype(F32), e.astype(F32)
        self.w, self.h = a.shape
        self.aspect = self.w / self.h


def squash(spr, f, darken=1.0):
    """כיווץ אנכי מעוגן לתחתית - לאנימציית מוות."""
    H = spr.h
    v = np.arange(H)
    src = ((v - H * (1 - f)) / f).astype(int)
    ok = src >= 0
    src = np.clip(src, 0, H - 1)
    rgb = spr.rgb[:, src] * darken
    a = spr.a[:, src] * ok[None, :]
    e = spr.e[:, src] * 0.3
    return Sprite(rgb, a, e)


SKIN = (0.86, 0.6, 0.46)
BONE = (0.93, 0.87, 0.72)


def draw_imp(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    skin, dark, belly = (0.78, 0.3, 0.17), (0.5, 0.17, 0.1), (0.88, 0.52, 0.34)
    hoof, eye = (0.16, 0.1, 0.09), (1.0, 0.85, 0.2)
    s = math.sin(phase)
    for side, sw in ((-1, s), (1, -s)):
        hx = 64 + side * 11
        kx, ky = hx + side * 3 + sw * 5, 101
        fx, fy = hx + side * 4 + sw * 9, 118
        c.capsule(hx, 80, kx, ky, 10, 7.5, dark)
        c.capsule(kx, ky, fx, fy, 7, 5, dark)
        c.ellipsoid(fx, 122, 8, 5, hoof, spec=0.4)
    c.ellipsoid(64, 76, 20, 14, dark)
    c.ellipsoid(64, 56, 27, 23, skin)
    c.ellipsoid(64, 65, 15, 13, belly, spec=0.12)
    for i in range(3):
        c.ellipsoid(64, 58 + i * 6, 12 - i * 2, 1.5, dark, spec=0)
    c.ellipsoid(40, 42, 11, 10, skin)
    c.ellipsoid(88, 42, 11, 10, skin)
    if pose == "attack":
        c.capsule(40, 44, 26, 62, 7, 6, skin)
        c.capsule(26, 62, 30, 80, 6, 5, skin)
        c.capsule(88, 42, 104, 28, 7, 6, skin)
        c.capsule(104, 28, 102, 15, 6, 5, skin)
        c.glow(102, 10, 14, (2.6, 1.1, 0.25), 1.4)
        c.glow(102, 10, 6, (2.0, 2.0, 1.2), 2.0)
    else:
        for side, sw in ((-1, -s), (1, s)):
            sx = 64 + side * 24
            ex, ey = sx + side * 8 + sw * 4, 64
            hx2, hy2 = sx + side * 6 + sw * 8, 84
            c.capsule(sx, 44, ex, ey, 7, 6, skin)
            c.capsule(ex, ey, hx2, hy2, 6, 5, skin)
            for k in (-1, 0, 1):
                c.capsule(hx2 + k * 3, hy2 + 3, hx2 + k * 4, hy2 + 9, 2, 1, BONE, spec=0.4)
    c.ellipsoid(64, 34, 10, 8, dark)
    c.ellipsoid(64, 24, 15, 14, skin)
    for side in (-1, 1):
        c.capsule(64 + side * 9, 15, 64 + side * 16, 8, 4.5, 3.2, BONE, spec=0.5)
        c.capsule(64 + side * 16, 8, 64 + side * 19, 2, 3.2, 1.3, BONE, spec=0.5)
    c.ellipsoid(58, 21, 6, 3, dark)
    c.ellipsoid(70, 21, 6, 3, dark)
    c.ellipsoid(58, 24, 3.2, 2.2, eye, emissive=1.6, spec=0.6)
    c.ellipsoid(70, 24, 3.2, 2.2, eye, emissive=1.6, spec=0.6)
    if pose == "attack":
        c.ellipsoid(64, 32, 7, 4.5, (0.12, 0.02, 0.02), spec=0)
        for k in range(-2, 3):
            c.ellipsoid(64 + k * 2.6, 29.6, 1.1, 1.6, BONE, spec=0.2)
    else:
        c.ellipsoid(64, 31, 6, 1.6, (0.25, 0.05, 0.04), spec=0)
    return c


def draw_brute(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    skin, dark, light = (0.42, 0.48, 0.34), (0.25, 0.3, 0.21), (0.55, 0.6, 0.45)
