    c.ellipsoid(64, 62, 11, 11, (1.0, 0.15, 0.1), emissive=hot, spec=0.9, shine=30)
    if pose == "attack":
        c.glow(64, 62, 26, (2.5, 0.3, 0.3), 2.0, alpha=False)
