    for side in (-1, 1):
        c.capsule(64 + side * 15, 62, 64 + side * 20, 75, 4, 3, skin)
        for k in (-1, 1):
            c.capsule(64 + side * 20 + k * 2, 75, 64 + side * 21 + k * 3, 80, 1.6, 0.7, claw)
