def draw_spitter(phase=0.0, pose="walk"):
    """יורק-חומצה - דינוזאור עם צווארון צבעוני שיורק חומצה ירוקה."""
    c = Canvas(128, 128)
    skin, dark, belly = (0.22, 0.44, 0.5), (0.12, 0.25, 0.3), (0.7, 0.75, 0.6)
    frill, eye = (0.98, 0.45, 0.12), (1.0, 0.9, 0.2)
    s = math.sin(phase)
    c.capsule(70, 82, 110 + s * 5, 70, 12, 3, dark)
    for side, sw in ((-1, s), (1, -s)):
        hx = 64 + side * 15
        c.capsule(hx, 86, hx + side * 3 + sw * 4, 108, 12, 9, skin)
        c.capsule(hx + side * 3 + sw * 4, 108, hx + side * 4 + sw * 6, 121, 8, 7, dark)
        c.rbox(hx + side * 4 + sw * 6, 123, 9, 4, (0.15, 0.15, 0.12), p=4)
    c.ellipsoid(64, 78, 26, 19, skin)
    c.ellipsoid(64, 84, 16, 11, belly, spec=0.1)
    for side in (-1, 1):
        c.capsule(64 + side * 17, 74, 64 + side * 21, 86, 4, 3, skin)
    if pose == "attack":
        c.ellipsoid(64, 26, 34, 24, frill, spec=0.3)
        for k in range(9):
            a = math.pi * (0.1 + 0.8 * k / 8)
            c.capsule(64, 30, 64 - math.cos(a) * 32, 30 - math.sin(a) * 22, 2, 1, (0.7, 0.1, 0.1), spec=0)
        for k in range(5):
            a = math.pi * (0.15 + 0.7 * k / 4)
            c.ellipsoid(64 - math.cos(a) * 24, 30 - math.sin(a) * 15, 3, 3, (0.2, 0.9, 0.9), emissive=0.8)
    c.capsule(64, 68, 64, 34, 9, 7, skin)
    if pose != "attack":
        for side in (-1, 1):
            c.ellipsoid(64 + side * 12, 28, 6, 9, frill, spec=0.3)
    c.ellipsoid(64, 26, 12, 10, skin)
    c.capsule(64, 18, 64, 3, 4, 1.8, frill, spec=0.4)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 8, 23, 3, 2.4, eye, emissive=0.8, spec=0.8)
        c.ellipsoid(64 + side * 8, 23, 0.7, 2.2, (0.02, 0.02, 0.02), spec=0)
    c.ellipsoid(64, 32, 8, 6, (0.3, 0.52, 0.56))
    if pose == "attack":
        c.ellipsoid(64, 35, 7, 5, (0.15, 0.3, 0.05), spec=0)
        c.glow(64, 36, 13, (0.6, 2.2, 0.3), 1.6)
    else:
        c.capsule(58, 35, 70, 35, 0.9, 0.9, (0.05, 0.1, 0.1), spec=0)
    return c


def draw_rex(phase=0.0, pose="walk"):
    """טירנוזאורוס - הבוס של שלב 3."""
    c = Canvas(128, 128)
    skin, dark, belly = (0.47, 0.38, 0.24), (0.27, 0.21, 0.13), (0.72, 0.63, 0.45)
    tooth, eye = (0.96, 0.93, 0.82), (1.0, 0.55, 0.05)
    s = math.sin(phase)
    c.capsule(70, 80, 116 + s * 5, 66, 17, 4, dark)
    for side, sw in ((-1, s), (1, -s)):
        hx = 64 + side * 18
        c.capsule(hx, 80, hx + side * 4 + sw * 3, 100, 17, 12, skin)
        c.capsule(hx + side * 4 + sw * 3, 100, hx + side * 3 + sw * 5, 117, 10, 8, dark)
        fx = hx + side * 3 + sw * 5
        c.rbox(fx, 121, 12, 5, dark, p=4)
        for k in (-1, 0, 1):
            c.capsule(fx + k * 6, 121, fx + k * 8, 127, 2.6, 1, tooth, spec=0.4)
    c.ellipsoid(64, 68, 31, 23, skin)
    c.ellipsoid(64, 76, 19, 13, belly, spec=0.1)
    for i in range(5):
        c.capsule(40 + i * 12, 52, 44 + i * 12, 60, 2.5, 1.8, dark, spec=0)
    for side in (-1, 1):
        c.capsule(64 + side * 17, 68, 64 + side * 21, 78, 4, 3, skin)
        c.capsule(64 + side * 21, 78, 64 + side * 22, 82, 1.6, 0.7, tooth)
    c.capsule(64, 60, 64, 42, 16, 14, skin)
    jaw_open = pose == "attack"
    c.ellipsoid(64, 28, 25, 18, skin)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 14, 20, 8, 4, dark)
        c.ellipsoid(64 + side * 14, 23, 3.2, 2.4, eye, emissive=1.0, spec=0.8)
        c.ellipsoid(64 + side * 14, 23, 0.8, 2.2, (0.02, 0.02, 0.02), spec=0)
    c.ellipsoid(64, 33, 19, 11, (0.53, 0.43, 0.28))
    c.ellipsoid(59, 27, 1.8, 1.3, (0.05, 0.04, 0.03), spec=0)
    c.ellipsoid(69, 27, 1.8, 1.3, (0.05, 0.04, 0.03), spec=0)
    if jaw_open:
        c.ellipsoid(64, 44, 17, 12, (0.4, 0.04, 0.04), spec=0.2)
        c.ellipsoid(64, 48, 9, 5, (0.7, 0.25, 0.25), spec=0.3)
        for k in range(-5, 6):
            c.capsule(64 + k * 2.9, 37, 64 + k * 2.9, 41.5, 1.3, 0.4, tooth, spec=0.4)
            c.capsule(64 + k * 2.9, 55, 64 + k * 2.9, 51, 1.3, 0.4, tooth, spec=0.4)
        c.ellipsoid(64, 58, 16, 4, skin)
    else:
        c.capsule(48, 42, 80, 42, 1.3, 1.3, (0.12, 0.07, 0.04), spec=0)
        for k in range(-4, 5):
            c.capsule(64 + k * 3.4, 41, 64 + k * 3.4, 44.5, 1.1, 0.4, tooth, spec=0.3)
        c.ellipsoid(64, 47, 16, 5, skin)
    return c


def make_jungle_props():
    c = Canvas(110, 220)
    pts = [(55 + 6 * math.sin(i * 0.35) + i * 0.4, 218 - i * 11) for i in range(16)]
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        c.capsule(x0, y0, x1, y1, 7.5, 6.5, (0.45, 0.33, 0.2), spec=0.15)
    for (x0, y0) in pts[1:-1]:
        c.capsule(x0 - 7, y0, x0 + 7, y0, 1.2, 1.2, (0.25, 0.17, 0.1), spec=0)
    tx, ty = pts[-1]
    for k in range(9):
        a = math.pi * 2 * k / 9 + 0.2
        L = 46
        prev = (tx, ty)
        for j in range(1, 9):
            t = j / 8
            x = tx + math.cos(a) * L * t
            y = ty - math.sin(a) * L * 0.35 * t + 30 * t * t
            r = 5.5 * (1 - t) + 1
            col = (0.16 + 0.05 * (k % 3), 0.45 + 0.05 * (k % 2), 0.12)
            c.capsule(prev[0], prev[1], x, y, r + 1, r, col, spec=0.25)
            nx, ny = -math.sin(a) * 0.4, math.cos(a)
            for sgn in (-1, 1):
                c.capsule(x, y, x + sgn * 8 * (1 - t * 0.5), y + 7, 1.6, 0.6, col, spec=0.2)
            prev = (x, y)
    for k in range(3):
        c.ellipsoid(tx - 5 + k * 5, ty + 6, 4.5, 4.5, (0.35, 0.22, 0.1), spec=0.4)
    palm = c.sprite()
    c = Canvas(96, 64)
    rr = random.Random(4)
    for k in range(13):
        a = math.pi * (0.08 + 0.84 * k / 12) + rr.uniform(-0.05, 0.05)
        L = rr.uniform(30, 44)
        prev = (48, 63)
        for j in range(1, 7):
            t = j / 6
            x = 48 + math.cos(a) * L * t
            y = 63 - math.sin(a) * L * t + 18 * t * t
            col = (0.15, 0.42 + 0.1 * (k % 2), 0.12)
            c.capsule(prev[0], prev[1], x, y, 3.2 * (1 - t) + 1, 3.2 * (1 - t * 0.9) + 0.6, col, spec=0.25)
            prev = (x, y)
    for k in range(4):
        c.ellipsoid(30 + k * 12, 34 + (k % 2) * 6, 3, 3, (0.95, 0.25, 0.45), spec=0.5)
    fern = c.sprite()
    return [palm] * 4, fern


def make_space_props():
    c = Canvas(40, 112)
    c.rbox(20, 106, 15, 6, (0.35, 0.37, 0.42), p=4, spec=0.7)
    c.capsule(20, 100, 20, 18, 6, 6, (0.4, 0.42, 0.48), spec=0.8, shine=30)
    c.rbox(20, 56, 7, 34, (0.75, 0.9, 1.0), p=6, emissive=1.8, spec=0.8)
    c.glow(20, 56, 22, (0.3, 0.5, 0.8), 2.0, alpha=False)
    c.rbox(20, 16, 12, 5, (0.4, 0.42, 0.48), p=4, spec=0.8)
    pillar = c.sprite()
    c = Canvas(64, 112)
    rr = random.Random(9)
    for i in range(7):
        bx = 32 + rr.uniform(-16, 16)
        top = 20 + rr.uniform(0, 50)
        c.capsule(bx, 108, bx + rr.uniform(-10, 10), top, rr.uniform(6, 10), 2, (0.85, 0.3, 0.95),
                  emissive=0.8, spec=0.9, shine=30)
    c.glow(32, 80, 34, (0.5, 0.1, 0.6), 2.0, alpha=False)
    crystal = c.sprite()
    return [pillar] * 4, crystal


