BLACK = (0.03, 0.03, 0.03)


def draw_wolf(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    fur, dark, eye = (0.78, 0.8, 0.85), (0.45, 0.48, 0.56), (0.3, 0.85, 1.0)
    s = math.sin(phase)
    c.ellipsoid(64, 70, 34, 20, dark)
    for side, sw in ((-1, s), (1, -s)):
        x = 64 + side * 16
        c.capsule(x, 78, x + side * 2 + sw * 4, 118, 8, 5.5, fur)
        c.ellipsoid(x + side * 2 + sw * 4, 120, 7, 4, dark)
    c.ellipsoid(64, 78, 21, 19, fur)
    for side in (-1, 1):
        c.capsule(64 + side * 14, 42, 64 + side * 22, 18, 7, 1.5, dark)
        c.ellipsoid(64 + side * 17, 60, 9, 10, fur)
    c.ellipsoid(64, 50, 20, 17, fur)
    c.ellipsoid(64, 62, 10, 9, (0.88, 0.89, 0.92))
    c.ellipsoid(64, 57, 4, 3, BLACK, spec=0.8)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 9, 46, 3.4, 2.4, eye, emissive=1.4, spec=0.8)
        c.capsule(64 + side * 4, 41, 64 + side * 13, 43, 1.5, 1.2, dark, spec=0)
    if pose == "attack":
        c.ellipsoid(64, 70, 9, 6, (0.45, 0.05, 0.05), spec=0.1)
        for k in (-1, 1):
            c.capsule(64 + k * 5, 65, 64 + k * 5, 71, 1.5, 0.4, (0.95, 0.95, 0.9))
            c.capsule(64 + k * 5, 76, 64 + k * 5, 71, 1.5, 0.4, (0.95, 0.95, 0.9))
    else:
        c.capsule(58, 68, 70, 68, 1, 1, BLACK, spec=0)
    return c


