def draw_mammoth(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    fur, dark, tusk, armor = (0.45, 0.3, 0.18), (0.27, 0.17, 0.1), (0.95, 0.92, 0.82), (0.5, 0.52, 0.58)
    s = math.sin(phase)
    for side, sw in ((-1, s), (1, -s)):
        c.capsule(64 + side * 28, 84, 64 + side * 30 + sw * 3, 124, 11, 10, dark)
    c.ellipsoid(64, 64, 48, 34, fur)
    for side, sw in ((-1, -s), (1, s)):
        c.capsule(64 + side * 18, 86, 64 + side * 20 + sw * 3, 122, 13, 12, fur)
        c.rbox(64 + side * 20 + sw * 3, 124, 12, 4, (0.6, 0.55, 0.45), p=4)
    c.ellipsoid(64, 30, 22, 14, fur)
    c.rbox(64, 28, 24, 8, armor, p=4, spec=0.9)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 30, 52, 11, 17, dark)
    c.ellipsoid(64, 52, 27, 25, fur)
    c.rbox(64, 38, 16, 6, armor, p=4, spec=0.9)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 11, 49, 3, 2.5, (1.0, 0.3, 0.1), emissive=1.2)
        pts = [(64 + side * 12, 66), (64 + side * 24, 80), (64 + side * 28, 96), (64 + side * 20, 106)]
        for (x0, y0), (x1, y1), r in zip(pts, pts[1:], (5.5, 4.5, 3.5)):
            c.capsule(x0, y0, x1, y1, r, r - 1, tusk, spec=0.6)
    if pose == "attack":
        pts = [(64, 62), (66, 42), (72, 26), (80, 18)]
    else:
        pts = [(64, 62), (64, 84), (62 + s * 3, 100), (66, 112)]
    for (x0, y0), (x1, y1), r in zip(pts, pts[1:], (8, 6.5, 5)):
        c.capsule(x0, y0, x1, y1, r, r - 1.2, fur)
    for k in range(9):
        x = 26 + k * 9.5
        c.capsule(x, 70, x + 1, 92, 1.4, 0.8, dark, spec=0)
    return c


