def draw_jelly(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    pink = (0.95, 0.5, 0.85)
    for k in range(7):
        x0 = 36 + k * 9.3
        prev = (x0, 56)
        for j in range(1, 7):
            y = 56 + j * 11
            x = x0 + math.sin(phase + j * 0.8 + k) * 4
            c.capsule(*prev, x, y, 3 - j * 0.35, 2.6 - j * 0.35, pink, emissive=0.8, spec=0.6)
            prev = (x, y)
    c.ellipsoid(64, 40, 34, 26, pink, emissive=0.5, spec=0.9, shine=30)
    hot = 2.4 if pose == "attack" else 1.3
    c.ellipsoid(64, 44, 18, 12, (1.0, 0.4, 1.0), emissive=hot, spec=0.5)
    if pose == "attack":
        c.glow(64, 44, 34, (1.6, 0.4, 1.6), 2, alpha=False)
    return c


def draw_octopus(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    purple, light = (0.55, 0.24, 0.62), (0.8, 0.55, 0.85)
    up = pose == "attack"
    for k in range(8):
        a = math.pi * (0.05 + 0.9 * k / 7)
        prev = (64 + math.cos(a) * 14, 70)
        for j in range(1, 8):
            t = j / 7
            x = 64 + math.cos(a) * (14 + 48 * t) + math.sin(phase + j + k) * 3
            y = 70 + (40 * t if not up else -30 * t * (1 if k in (0, 7) else -0.8)) + math.sin(a) * 18 * t
            r = 9 * (1 - t) + 2
            c.capsule(*prev, x, y, r + 0.8, r, purple, spec=0.5)
            if j % 2 == 0:
                c.ellipsoid(x, y + 2, r * 0.4, r * 0.4, light, spec=0.4)
            prev = (x, y)
    c.ellipsoid(64, 36, 32, 34, purple, spec=0.6)
    for k in range(6):
        c.ellipsoid(50 + (k % 3) * 14, 18 + (k // 3) * 12, 3, 3, light, spec=0.3)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 15, 48, 10, 8, (1.0, 0.85, 0.3), emissive=1.2 if up else 0.5, spec=0.9)
        c.rbox(64 + side * 15, 48, 7, 1.6, BLACK, p=4, spec=0)
    return c


def draw_mummy(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    band, dark = (0.84, 0.78, 0.6), (0.42, 0.36, 0.25)
    s = math.sin(phase)
    for side, sw in ((-1, s), (1, -s)):
        x = 64 + side * 9
        c.capsule(x, 78, x + sw * 3, 120, 7.5, 6, band)
    c.ellipsoid(64, 60, 20, 24, band)
    raise_ = 12 if pose == "attack" else 0
    for side in (-1, 1):
        c.capsule(64 + side * 19, 44, 64 + side * 11, 56 - raise_, 6.5, 5.5, band)
        c.ellipsoid(64 + side * 10, 58 - raise_, 6, 5, band)
    c.ellipsoid(64, 22, 14, 16, band)
    rr = random.Random(7)
    a_body = c.a.copy()
    for k in range(26):
        y = 8 + k * 4.4
        w = 26 if y < 38 else (22 if y < 82 else 16)
        c.capsule(64 - w, y + rr.uniform(-1, 1), 64 + w, y + rr.uniform(-2, 2), 0.8, 0.8, dark, spec=0)
    c.a = a_body       # פסי התחבושת רק על הגוף
    c.capsule(80, 70, 92, 104 + s * 3, 2.5, 1.5, band)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 6, 20, 3.4, 2.4, (0.3, 1.0, 0.4), emissive=2.0)
    return c


def draw_scorpion(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    shell, dark, sting = (0.3, 0.2, 0.12), (0.15, 0.1, 0.07), (0.9, 0.85, 0.2)
    s = math.sin(phase)
    for side in (-1, 1):
        for k in range(3):
            y = 92 + k * 7
            c.capsule(64 + side * 18, y, 64 + side * (44 + k * 6), y + 14 + s * side * 3, 3, 1.5, dark, spec=0.6)
    up = 8 if pose == "attack" else 0
    pts = [(64, 84), (64, 64), (67, 44 - up), (70, 28 - up), (64, 18 - up)]
    for (x0, y0), (x1, y1), r in zip(pts, pts[1:], (10, 8.5, 7, 6)):
        c.capsule(x0, y0, x1, y1, r, r - 1, shell, spec=0.9, shine=30)
    c.ellipsoid(64, 18 - up, 6, 6, sting, emissive=1.8 if pose == "attack" else 0.6, spec=0.9)
    c.ellipsoid(64, 94, 26, 15, shell, spec=0.9, shine=30)
    for side in (-1, 1):
        c.capsule(64 + side * 18, 92, 64 + side * 34, 76, 5, 4, shell, spec=0.8)
        cx, cy = 64 + side * 40, 70
        c.ellipsoid(cx, cy, 10, 8, shell, spec=0.9, shine=30)
        c.capsule(cx + side * 4, cy - 6, cx + side * 10, cy - 16, 4, 1.5, shell, spec=0.8)
        c.capsule(cx - side * 2, cy - 6, cx - side * 2, cy - 15, 3.5, 1.2, shell, spec=0.8)
    for k in (-1, 0, 1):
        c.ellipsoid(64 + k * 4, 86, 1.6, 1.6, (1.0, 0.1, 0.1), emissive=1.5)
    return c


def draw_jackal(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    stone, gold, lapis = (0.55, 0.53, 0.48), (0.88, 0.7, 0.25), (0.15, 0.3, 0.65)
    eye = (0.3, 1.0, 0.55)
    s = math.sin(phase)
    for side, sw in ((-1, s), (1, -s)):
        x = 64 + side * 11
        c.capsule(x, 80, x + sw * 3, 120, 8, 7, stone)
        c.rbox(x + sw * 3, 123, 9, 4, gold, p=4, spec=0.8)
    c.rbox(64, 82, 22, 9, gold, p=5, spec=0.8)
    c.ellipsoid(64, 60, 22, 22, stone)
    c.ellipsoid(64, 44, 26, 9, gold, spec=0.8)
    for k in range(3):
        c.ellipsoid(64, 41 + k * 3.5, 24 - k * 2, 1.2, lapis, spec=0.3)
    for side in (-1, 1):
        c.capsule(64 + side * 24, 46, 64 + side * 28, 76, 6.5, 5.5, stone)
    if pose == "attack":
        c.capsule(92, 20, 92, 110, 2.8, 2.8, gold, spec=0.9)
        c.glow(92, 16, 16, (2.4, 2.0, 0.5), 1.6)
    else:
        c.capsule(92, 40, 92, 120, 2.8, 2.8, gold, spec=0.9)
        c.ellipsoid(92, 38, 5, 5, gold, spec=0.9)
    c.ellipsoid(64, 26, 13, 13, stone)
    for side in (-1, 1):
        c.capsule(64 + side * 7, 16, 64 + side * 11, -2, 5.5, 1.5, stone)
        c.capsule(64 + side * 7, 14, 64 + side * 10, 2, 2.5, 0.8, gold, spec=0.6)
    c.ellipsoid(64, 36, 7, 9, stone)
    c.ellipsoid(64, 43, 3, 2, BLACK, spec=0.5)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 6, 24, 3, 2, eye, emissive=2.2 if pose == "attack" else 1.4)
    for k in range(6):
        c.capsule(48 + k * 6, 52 + (k % 3) * 8, 52 + k * 6, 58 + (k % 2) * 6, 0.6, 0.6, (0.25, 0.24, 0.22), spec=0)
    return c


def draw_cube(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    col = (0.2, 0.85, 1.0)
    sq = 1 + math.sin(phase) * 0.08
    h = 40 / sq
    c.rbox(64, 128 - h - 2, 42, h + 2, (0.1, 0.4, 0.6), p=14, emissive=0.6)
    c.rbox(64, 128 - h - 2, 38, h - 2, col, p=14, emissive=0.35, spec=0.6)
    cy = 128 - h - 8
    for side in (-1, 1):
        c.rbox(64 + side * 14, cy - 6, 6, 8, BLACK, p=20, spec=0)
        c.rbox(64 + side * 12, cy - 9, 2, 2, (1, 1, 1), p=20, emissive=1.5)
    if pose == "attack":
        c.rbox(64, cy + 14, 18, 7, (0.4, 0.0, 0.1), p=20, spec=0)
    else:
        c.rbox(64, cy + 12, 14, 2.5, BLACK, p=20, spec=0)
    return c


def draw_bug(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    green, mag = (0.3, 1.0, 0.4), (1.0, 0.2, 0.8)
    s = math.sin(phase)
    for side in (-1, 1):
        for k in range(3):
            y = 66 + k * 14
            c.rbox(64 + side * 30, y + s * side * 3, 14, 2.5, mag, p=20, emissive=0.6)
            c.rbox(64 + side * 42, y + 8 + s * side * 3, 2.5, 8, mag, p=20, emissive=0.6)
    c.rbox(64, 92, 20, 22, green, p=20, emissive=0.3, spec=0.3)
    for k in range(3):
        c.rbox(64, 80 + k * 10, 20, 1.5, (0.1, 0.4, 0.15), p=20)
    c.rbox(64, 62, 15, 10, green, p=20, emissive=0.3)
    c.rbox(64, 42, 15, 12, green, p=20, emissive=0.3)
    for side in (-1, 1):
        c.rbox(64 + side * 8, 40, 4, 4, (1.0, 0.1, 0.1), p=20, emissive=2.0)
        c.rbox(64 + side * 10, 26, 2, 6, mag, p=20, emissive=0.8)
        c.rbox(64 + side * 15, 18, 4, 2, mag, p=20, emissive=0.8)
    rr = random.Random(int(phase * 10))
    for k in range(3):
        y = rr.uniform(20, 110)
        c.rbox(64 + rr.uniform(-20, 20), y, rr.uniform(10, 30), 1.5,
               ((0.2, 1, 1), (1, 1, 0.2), (1, 0.2, 0.8))[k], p=20, emissive=1.5)
    return c


def draw_virus(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    core, spike = (0.3, 0.9, 0.4), (1.0, 0.2, 0.8)
    for k in range(14):
        a = 2 * math.pi * k / 14 + phase * 0.3
        x0, y0 = 64 + math.cos(a) * 30, 64 + math.sin(a) * 30
        x1, y1 = 64 + math.cos(a) * 56, 64 + math.sin(a) * 56
        c.capsule(x0, y0, x1, y1, 5, 2, spike, emissive=0.5, spec=0.6)
        c.ellipsoid(x1, y1, 4.5, 4.5, spike, emissive=1.8)
    c.ellipsoid(64, 64, 36, 36, core, emissive=0.35, spec=0.8, shine=30)
    for k in range(6):
        a = k * 1.1
        c.ellipsoid(64 + math.cos(a) * 20, 64 + math.sin(a) * 22, 5, 5, (0.2, 0.6, 0.3), spec=0.3)
    for side in (-1, 1):
        c.rbox(64 + side * 12, 56, 7, 6, (1, 1, 1), p=20, emissive=0.6)
        c.rbox(64 + side * 10, 57, 3, 4, BLACK, p=20, spec=0)
        c.capsule(64 + side * 4, 46, 64 + side * 20, 50, 2, 2, BLACK, spec=0)
    hot = pose == "attack"
    for k in range(-3, 3):
        c.capsule(64 + k * 5, 76 + (k % 2) * 4, 64 + (k + 1) * 5, 76 + ((k + 1) % 2) * 4, 1.6, 1.6,
                  (1.0, 0.2, 0.2) if hot else BLACK, emissive=1.5 if hot else 0, spec=0)
    if hot:
        c.glow(64, 64, 50, (1.0, 0.2, 0.8), 2.0, alpha=False)
    return c


EXTRA_DRAW = {"wolf": draw_wolf, "snowman": draw_snowman, "mammoth": draw_mammoth, "zombie": draw_zombie,
              "guardbot": draw_guardbot, "spidertank": draw_spidertank, "shark": draw_shark, "jelly": draw_jelly,
              "octopus": draw_octopus, "mummy": draw_mummy, "scorpion": draw_scorpion, "jackal": draw_jackal,
              "cube": draw_cube, "bug": draw_bug, "virus": draw_virus}


# ---------------------------------------------------------------- עצמים לשלבים 4-8
def make_lamp_post(glow_col, pole=(0.18, 0.19, 0.22), w=40, h=150):
    c = Canvas(w, h)
    c.rbox(w / 2, h - 4, 10, 4, pole, p=4, spec=0.6)
    c.capsule(w / 2, h - 6, w / 2, 26, 3.2, 2.6, pole, spec=0.7)
    c.capsule(w / 2, 26, w / 2 + 10, 16, 2.6, 2.4, pole, spec=0.7)
    c.rbox(w / 2 + 10, 18, 9, 5, pole, p=4, spec=0.7)
    c.ellipsoid(w / 2 + 10, 24, 7, 4, glow_col, emissive=2.0, spec=0.6)
    c.glow(w / 2 + 10, 26, 18, tuple(v * 0.5 for v in glow_col), 2.0, alpha=False)
    return c.sprite()


def make_pine():
    c = Canvas(96, 160)
    c.capsule(48, 158, 48, 120, 6, 5, (0.35, 0.23, 0.13))
    for k in range(5):
        y = 128 - k * 24
        w = 44 - k * 8
        c.ellipsoid(48, y, w, 16, (0.1, 0.3, 0.16), spec=0.2)
        c.ellipsoid(48, y - 9, w * 0.8, 6, (0.93, 0.95, 1.0), spec=0.4)
    c.ellipsoid(48, 12, 7, 10, (0.93, 0.95, 1.0), spec=0.4)
    return c.sprite()


def make_fire_barrel():
    frames = []
    for k in range(4):
        c = Canvas(48, 64)
        c.rbox(24, 46, 15, 17, (0.42, 0.22, 0.12), p=4, spec=0.4)
        for y in (34, 46, 58):
            c.rbox(24, y, 15.5, 1.5, (0.25, 0.14, 0.08), p=4)
        rr = random.Random(k + 20)
        for i in range(5):
            c.glow(24 + rr.uniform(-4, 4), 26 - i * 4 + rr.uniform(-2, 2), 11 - i * 1.6, (2.2, 0.8, 0.15), 1.3)
        frames.append(c.sprite())
    return frames


def make_kelp():
    c = Canvas(64, 128)
    for k in range(4):
        x0 = 18 + k * 10
        prev = (x0, 127)
        for j in range(1, 10):
            y = 127 - j * 12
            x = x0 + math.sin(j * 0.7 + k) * 6
            c.capsule(*prev, x, y, 3.5, 3, (0.25 + 0.05 * k, 0.42, 0.12), spec=0.4)
            c.ellipsoid(x + 4, y, 4, 2, (0.3, 0.5, 0.15), spec=0.3)
            prev = (x, y)
    return c.sprite()


def make_neon_pillar():
    c = Canvas(40, 128)
    c.rbox(20, 122, 14, 6, (0.1, 0.05, 0.15), p=8, emissive=0.3)
    c.rbox(20, 64, 7, 54, (1.0, 0.25, 0.9), p=12, emissive=1.8, spec=0.6)
    c.rbox(20, 8, 12, 6, (0.1, 0.05, 0.15), p=8, emissive=0.3)
    c.glow(20, 64, 26, (0.6, 0.1, 0.6), 2.0, alpha=False)
    return c.sprite()


def make_cube_tree():
    c = Canvas(64, 128)
    c.rbox(32, 104, 6, 24, (0.45, 0.25, 0.1), p=20, spec=0.2)
    for x, y, s in ((32, 40, 22), (16, 58, 13), (48, 58, 13), (32, 20, 13), (22, 34, 12), (44, 30, 12)):
        c.rbox(x, y, s, s, (0.2, 0.9, 0.35), p=20, emissive=0.35, spec=0.4)
    return c.sprite()


def make_extra_props(theme):
    if theme == "arctic":
        return [make_lamp_post((1.0, 0.7, 0.35))] * 4, make_pine()
    if theme == "city":
        return [make_lamp_post((1.0, 0.85, 0.55), w=44, h=170)] * 4, make_fire_barrel()
    if theme == "ocean":
        return [make_lamp_post((0.3, 1.0, 1.0), (0.3, 0.32, 0.3), 40, 110)] * 4, make_kelp()
    if theme == "desert":
        return make_props()[0], make_jungle_props()[0][0]
    if theme == "pixel":
        return [make_neon_pillar()] * 4, make_cube_tree()


# ---------------------------------------------------------------- אויבים לשלבים 9-12 (עיצובים מקוריים)


def draw_gummy(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    col = (0.95, 0.15, 0.25)
    s = math.sin(phase)
    for side, sw in ((-1, s), (1, -s)):
        c.ellipsoid(64 + side * 15, 112 + sw * 2, 12, 14, col, emissive=0.3, spec=1.0, shine=30)
    c.ellipsoid(64, 84, 26, 28, col, emissive=0.3, spec=1.0, shine=30)
    c.ellipsoid(64, 88, 15, 16, (1.0, 0.45, 0.5), emissive=0.3, spec=0.8, shine=30)
    up = 14 if pose == "attack" else 0
    for side in (-1, 1):
        c.ellipsoid(64 + side * 27, 74 - up, 9, 13, col, emissive=0.3, spec=1.0, shine=30)
        c.ellipsoid(64 + side * 17, 22, 9, 9, col, emissive=0.3, spec=1.0, shine=30)
    c.ellipsoid(64, 42, 23, 21, col, emissive=0.3, spec=1.0, shine=30)
    c.ellipsoid(64, 50, 10, 7, (1.0, 0.45, 0.5), emissive=0.3, spec=0.8)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 8, 38, 3, 3.6, BLACK, spec=1.0, shine=40)
        c.capsule(64 + side * 4, 31, 64 + side * 12, 33, 1.3, 1.1, (0.5, 0.05, 0.1), spec=0)
    c.ellipsoid(64, 47, 3, 2, (0.4, 0.05, 0.08), spec=0.5)
    if pose == "attack":
        c.ellipsoid(64, 55, 6, 4, (0.4, 0.02, 0.05), spec=0)
    return c


def draw_cupcake(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    s = math.sin(phase)
    for side, sw in ((-1, s), (1, -s)):
        c.capsule(64 + side * 12, 108, 64 + side * 14 + sw * 3, 124, 4, 3.5, (0.6, 0.35, 0.2))
    c.rbox(64, 96, 28, 18, (0.4, 0.75, 0.95), p=3, spec=0.4)
    for k in range(-6, 7):
        c.capsule(64 + k * 4.4, 80, 64 + k * 3.8, 112, 1, 1, (0.25, 0.5, 0.75), spec=0)
    for i, (y, w) in enumerate(((74, 36), (58, 30), (44, 22), (32, 13))):
        c.ellipsoid(64, y, w, 11, (1.0, 0.75 - i * 0.05, 0.85), spec=0.5)
    pal = ((1, 0.2, 0.3), (0.2, 0.7, 1), (1, 0.9, 0.2), (0.3, 0.9, 0.4))
    rr = random.Random(3)
    for k in range(16):
        x, y = 64 + rr.uniform(-28, 28), rr.uniform(36, 78)
        c.capsule(x - 2, y, x + 2, y + rr.uniform(-1.5, 1.5), 1.2, 1.2, pal[k % 4], spec=0.4)
    c.ellipsoid(64, 18, 8, 8, (0.85, 0.05, 0.1), spec=1.0, shine=40)
    c.capsule(66, 12, 72, 2, 1, 0.8, (0.2, 0.5, 0.15))
    for side in (-1, 1):
        c.ellipsoid(64 + side * 10, 58, 5, 5.5, (1, 1, 1), spec=0.4)
        c.ellipsoid(64 + side * 10, 59, 2.4, 3, BLACK, spec=0.6)
        c.capsule(64 + side * 4, 50, 64 + side * 16, 53, 1.4, 1.2, (0.5, 0.2, 0.3), spec=0)
        c.capsule(64 + side * 28, 80, 64 + side * 38, 66 - (12 if pose == "attack" else 0), 3, 2.5, (0.6, 0.35, 0.2))
    if pose == "attack":
        c.ellipsoid(64, 70, 10, 6, (0.35, 0.05, 0.1), spec=0)
        for k in range(5):
            c.ellipsoid(56 + k * 4, 70, 1.5, 1.5, pal[k % 4], emissive=1.5)
    else:
        c.capsule(56, 70, 72, 70, 1.3, 1.3, (0.4, 0.1, 0.2), spec=0)
    return c


def draw_cakegolem(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    s = math.sin(phase)
    for side, sw in ((-1, s), (1, -s)):
        c.rbox(64 + side * 16, 116 + sw * 2, 10, 11, (0.38, 0.2, 0.1), p=4)
    tiers = ((96, 40, 14, (0.38, 0.2, 0.1)), (68, 32, 13, (0.98, 0.65, 0.8)), (44, 24, 11, (0.98, 0.95, 0.9)))
    for y, w, h, col in tiers:
        c.rbox(64, y, w, h, col, p=4, spec=0.3)
        for k in range(-w + 4, w - 3, 7):
            c.ellipsoid(64 + k, y - h + 4, 4.5, 5 + (k * 7 % 5), (1.0, 0.95, 0.97), spec=0.6)
    for k in range(-2, 3):
        x = 64 + k * 9
        c.capsule(x, 32, x, 22, 2, 2, ((1, 0.3, 0.4), (0.3, 0.7, 1))[k % 2], spec=0.4)
        c.glow(x, 17, 6, (2.2, 1.4, 0.4), 1.5)
    up = 30 if pose == "attack" else 0
    for side in (-1, 1):
        pts = [(64 + side * 34, 66), (64 + side * 52, 72 - up), (64 + side * 56, 92 - up * 1.6)]
        for j, ((x0, y0), (x1, y1)) in enumerate(zip(pts, pts[1:])):
            for k in range(4):
                t0, t1 = k / 4, (k + 1) / 4
                c.capsule(x0 + (x1 - x0) * t0, y0 + (y1 - y0) * t0, x0 + (x1 - x0) * t1, y0 + (y1 - y0) * t1,
                          5, 5, (0.9, 0.12, 0.15) if (j * 4 + k) % 2 else (0.97, 0.95, 0.95), spec=0.7)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 11, 64, 6, 6, (0.9, 0.05, 0.1), emissive=1.2, spec=1.0, shine=40)
    c.ellipsoid(64, 78, 14, 5 + (4 if pose == "attack" else 0), (0.25, 0.1, 0.05), spec=0)
    return c


def draw_ghost(phase=0.0, pose="walk"):
    """רוח רפאים - ברדס קרוע ומרחף."""
    c = Canvas(128, 128)
    white = (0.82, 0.9, 1.0)
    for k in range(9):
        x = 30 + k * 8.5
        c.capsule(x, 70, x + math.sin(phase + k) * 5, 112 + (k % 3) * 6, 9, 2, white, emissive=0.5, spec=0.2)
    c.ellipsoid(64, 66, 34, 34, white, emissive=0.5, spec=0.3)
    c.ellipsoid(64, 34, 24, 24, white, emissive=0.5, spec=0.3)
    c.ellipsoid(64, 38, 16, 18, (0.05, 0.06, 0.12), spec=0)
    hot = pose == "attack"
    for side in (-1, 1):
        c.ellipsoid(64 + side * 6, 34, 3, 2.4, (0.4, 1.0, 0.7), emissive=2.4 if hot else 1.4)
        up = 26 if hot else 0
        c.capsule(64 + side * 30, 56, 64 + side * 48, 76 - up, 8, 4, white, emissive=0.5)
    if hot:
        c.glow(64, 30, 22, (0.3, 1.0, 0.7), 2.0, alpha=False)
    return c


def draw_skeleton(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    bone, dark = (0.92, 0.9, 0.8), (0.2, 0.18, 0.15)
    s = math.sin(phase)
    for side, sw in ((-1, s), (1, -s)):
        x = 64 + side * 9
        c.capsule(x, 74, x + sw * 2, 98, 3, 2.5, bone)
        c.ellipsoid(x + sw * 2, 98, 4, 4, bone)
        c.capsule(x + sw * 2, 98, x + sw * 4, 120, 2.5, 2.2, bone)
        c.rbox(x + sw * 4 + side * 2, 123, 6, 3, bone, p=4)
    c.ellipsoid(64, 72, 14, 6, bone)
    c.capsule(64, 70, 64, 30, 2.5, 2.5, bone)
    for k in range(5):
        y = 38 + k * 6
        w = 15 - k * 1.4
        c.capsule(64 - w, y + 3, 64 + w, y + 3, 1.8, 1.8, bone, spec=0.3)
    raise_ = pose == "attack"
    c.capsule(48, 34, 42, 56, 2.5, 2.2, bone)
    c.capsule(42, 56, 40, 76, 2.2, 2, bone)
    if raise_:
        c.capsule(80, 34, 92, 20, 2.5, 2.2, bone)
        c.capsule(92, 18, 96, -4, 3, 1.5, (0.5, 0.5, 0.52), spec=0.9)
    else:
        c.capsule(80, 34, 86, 56, 2.5, 2.2, bone)
        c.capsule(86, 56, 90, 64, 2.2, 2, bone)
        c.capsule(90, 60, 100, 100, 3, 1.5, (0.5, 0.5, 0.52), spec=0.9)
        c.capsule(84, 64, 96, 62, 2, 2, (0.4, 0.28, 0.15))
    c.ellipsoid(64, 18, 12, 13, bone, spec=0.4)
    c.ellipsoid(64, 27, 8, 5, bone)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 5, 17, 3.6, 4, dark, spec=0)
        c.ellipsoid(64 + side * 5, 17, 1, 1, (1, 0.2, 0.1), emissive=2.5)
    for k in range(-2, 3):
        c.capsule(64 + k * 2.5, 26, 64 + k * 2.5, 30, 0.8, 0.8, dark, spec=0)
    return c


def draw_shadowking(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    cloak, inner, gold = (0.12, 0.08, 0.16), (0.5, 0.05, 0.1), (0.95, 0.75, 0.25)
    s = math.sin(phase)
    c.ellipsoid(64, 74, 46, 50, inner, spec=0.3)
    c.ellipsoid(64, 78, 30, 48, cloak, spec=0.5)
    for k in range(5):
        c.capsule(44 + k * 10, 100, 44 + k * 10 + s * 2, 126, 6, 3, cloak, spec=0.3)
    c.ellipsoid(64, 38, 26, 10, gold, spec=0.8)
    c.ellipsoid(64, 37, 22, 6, cloak, spec=0.3)
    c.ellipsoid(64, 22, 12, 14, (0.72, 0.7, 0.75), spec=0.3)
    c.rbox(64, 9, 13, 4, gold, p=4, spec=0.9)
    for k in range(-2, 3):
        c.capsule(64 + k * 6, 8, 64 + k * 6, 0, 2, 0.6, gold, spec=0.9)
    c.ellipsoid(64, 7, 2.2, 2.2, (0.6, 0.1, 1.0), emissive=2)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 5, 21, 3, 1.8, (1, 0.1, 0.1), emissive=2.6)
    c.capsule(58, 30, 70, 30, 1, 1, (0.3, 0.2, 0.25), spec=0)
    hot = pose == "attack"
    for side in (-1, 1):
        hx, hy = 64 + side * 30, 56 - (20 if hot else 0)
        c.capsule(64 + side * 20, 44, hx, hy, 7, 5, cloak)
        c.ellipsoid(hx, hy + 4, 5, 5, (0.72, 0.7, 0.75))
        if hot:
            c.glow(hx, hy - 4, 16, (1.2, 0.3, 2.2), 1.6)
    return c


def draw_crawler(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    shell, dark, eye = (0.6, 0.25, 0.12), (0.25, 0.1, 0.06), (1.0, 0.85, 0.2)
    s = math.sin(phase)
    for side in (-1, 1):
        for k in range(3):
            y = 92 + k * 6
            sw = s * (1 if k % 2 else -1) * side
            c.capsule(64 + side * 18, y, 64 + side * (40 + k * 4), y - 16 + sw * 3, 3.5, 2.5, dark, spec=0.6)
            c.capsule(64 + side * (40 + k * 4), y - 16 + sw * 3, 64 + side * (48 + k * 5), 124, 2.5, 1, dark, spec=0.6)
    c.ellipsoid(64, 98, 26, 16, shell, spec=0.9, shine=30)
    for k in range(3):
        c.capsule(44, 92 + k * 6, 84, 92 + k * 6, 1, 1, dark, spec=0)
    c.ellipsoid(64, 80, 17, 12, shell, spec=0.9, shine=30)
    for x, y in ((56, 76), (72, 76), (60, 71), (68, 71)):
        c.ellipsoid(x, y, 2.8, 2.8, eye, emissive=1.6, spec=0.8)
    op = 6 if pose == "attack" else 0
    for side in (-1, 1):
        c.capsule(64 + side * 6, 88, 64 + side * (12 + op), 100, 3, 1, (0.9, 0.85, 0.7), spec=0.6)
    return c


def draw_eyeorb(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    for k in range(6):
        x0 = 44 + k * 8
        prev = (x0, 84)
        for j in range(1, 5):
            y = 84 + j * 9
            x = x0 + math.sin(phase + j + k) * 4
            c.capsule(*prev, x, y, 3 - j * 0.5, 2.6 - j * 0.5, (0.55, 0.2, 0.3), spec=0.5)
            prev = (x, y)
    c.ellipsoid(64, 56, 34, 34, (0.95, 0.92, 0.88), spec=0.9, shine=30)
    rr = random.Random(5)
    for k in range(10):
        a = rr.uniform(0, 2 * math.pi)
        r0, r1 = 30, 18
        c.capsule(64 + math.cos(a) * r0, 56 + math.sin(a) * r0, 64 + math.cos(a + 0.3) * r1,
                  56 + math.sin(a + 0.3) * r1, 0.7, 0.4, (0.8, 0.1, 0.1), spec=0)
    hot = pose == "attack"
    c.ellipsoid(64, 58, 15, 15, (0.2, 0.9, 0.3), emissive=1.6 if hot else 0.7, spec=0.9)
    c.ellipsoid(64, 58, 6, 9 if not hot else 4, BLACK, spec=1.0, shine=40)
    c.ellipsoid(58, 52, 3, 3, (1, 1, 1), emissive=1)
    return c


def draw_worm(phase=0.0, pose="walk"):
    """תולעת חול ענקית שמתרוממת מהקרקע - מבט אל הפה."""
    c = Canvas(128, 128)
    skin, dark, tooth = (0.78, 0.55, 0.42), (0.5, 0.32, 0.24), (0.95, 0.92, 0.82)
    s = math.sin(phase)
    c.ellipsoid(64, 122, 46, 8, (0.62, 0.32, 0.18), spec=0.1)
    for k in range(7):
        y = 118 - k * 12
        w = 30 - k * 1.2
        c.ellipsoid(64 + s * k * 0.8, y, w, 9, skin if k % 2 else dark, spec=0.5)
    head = (64 + s * 6, 30)
    c.ellipsoid(*head, 34, 26, skin, spec=0.5)
    open_ = pose == "attack"
    r = 20 if open_ else 13
    c.ellipsoid(*head, r, r * 0.8, (0.35, 0.05, 0.08), spec=0.2)
    c.ellipsoid(head[0], head[1] + 2, r * 0.5, r * 0.4, (0.15, 0.02, 0.04), spec=0)
    for ring, rr_ in ((r, 3.2), (r * 0.65, 2.2)):
        for k in range(16):
            a = 2 * math.pi * k / 16
            x0, y0 = head[0] + math.cos(a) * ring, head[1] + math.sin(a) * ring * 0.8
            x1, y1 = head[0] + math.cos(a) * (ring - 7), head[1] + math.sin(a) * (ring - 7) * 0.8
            c.capsule(x0, y0, x1, y1, rr_, 0.5, tooth, spec=0.5)
    return c


def draw_shroomman(phase=0.0, pose="walk"):
    """איש פטרייה - כובע טורקיז עם כתמים זוהרים."""
    c = Canvas(128, 128)
    stem, cap, spot = (0.86, 0.8, 0.66), (0.12, 0.5, 0.55), (0.6, 1.0, 0.9)
    s = math.sin(phase)
    for side, sw in ((-1, s), (1, -s)):
        c.capsule(64 + side * 10, 100, 64 + side * 12 + sw * 3, 122, 6, 5, stem)
    c.ellipsoid(64, 82, 22, 26, stem, spec=0.3)
    up = 18 if pose == "attack" else 0
    for side in (-1, 1):
        c.capsule(64 + side * 20, 72, 64 + side * 34, 92 - up, 5, 4, stem)
    c.ellipsoid(64, 42, 46, 18, (0.75, 0.72, 0.6), spec=0.2)
    for k in range(-5, 6):
        c.capsule(64 + k * 7, 46, 64 + k * 5, 56, 1, 1, (0.6, 0.55, 0.45), spec=0)
    c.ellipsoid(64, 34, 48, 26, cap, spec=0.7, shine=24)
    rr = random.Random(11)
    for k in range(8):
        c.ellipsoid(64 + rr.uniform(-34, 34), rr.uniform(18, 40), rr.uniform(3, 6), rr.uniform(2.5, 4), spot,
                    emissive=1.3, spec=0.5)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 8, 70, 3.4, 4, BLACK, spec=1.0, shine=40)
        c.capsule(64 + side * 3, 63, 64 + side * 13, 65, 1.3, 1.1, (0.4, 0.3, 0.2), spec=0)
    c.ellipsoid(64, 82, 6, 3 + (3 if pose == "attack" else 0), (0.3, 0.15, 0.1), spec=0)
    return c


def draw_puffer(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    body, spot = (0.55, 0.3, 0.7), (1.0, 0.5, 1.0)
    sq = 1 + math.sin(phase) * 0.06
    c.capsule(64, 124, 64, 100, 10, 8, (0.75, 0.7, 0.6))
    c.ellipsoid(64, 70, 40 * sq, 36 / sq, body, spec=0.6)
    rr = random.Random(2)
    for k in range(12):
        a = rr.uniform(0, 2 * math.pi)
        d = rr.uniform(8, 30)
        c.ellipsoid(64 + math.cos(a) * d, 70 + math.sin(a) * d * 0.85, 3.5, 3.5, spot, emissive=1.4, spec=0.4)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 12, 64, 4, 4.5, BLACK, spec=1.0, shine=40)
    hot = pose == "attack"
    c.ellipsoid(64, 80, 7 if hot else 4, 6 if hot else 2, (0.2, 0.05, 0.2), spec=0)
    if hot:
        for k in range(6):
            c.glow(64 + rr.uniform(-20, 20), 30 + rr.uniform(-15, 10), 8, (1.4, 0.5, 1.6), 1.8)
    return c


def draw_spiderqueen(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    body, dark, eye = (0.2, 0.12, 0.25), (0.1, 0.06, 0.12), (1.0, 0.15, 0.1)
    s = math.sin(phase)
    c.ellipsoid(64, 56, 40, 34, body, spec=0.9, shine=30)
    for k in range(4):
        c.ellipsoid(64, 40 + k * 9, 16 - k * 2.5, 3, (0.9, 0.3, 1.0), emissive=1.2, spec=0.3)
    for side in (-1, 1):
        for k in range(4):
            sw = s * (1 if k % 2 else -1) * side
            kx = 64 + side * (34 + k * 6)
            ky = 52 + k * 10 - 26
            c.capsule(64 + side * 20, 80 + k * 3, kx, ky + sw * 4, 4.5, 3.5, dark, spec=0.7)
            c.capsule(kx, ky + sw * 4, 64 + side * (40 + k * 7), 126, 3.5, 1.2, dark, spec=0.7)
    c.ellipsoid(64, 86, 22, 17, body, spec=0.9, shine=30)
    for x, y, r in ((56, 82, 4), (72, 82, 4), (50, 76, 2.5), (78, 76, 2.5), (60, 76, 2.5), (68, 76, 2.5),
                    (64, 74, 3)):
        c.ellipsoid(x, y, r, r, eye, emissive=2.0, spec=0.8)
    op = 4 if pose == "attack" else 0
    for side in (-1, 1):
        c.capsule(64 + side * 6, 94, 64 + side * (8 + op), 108, 3, 1, (0.85, 0.8, 0.7), spec=0.6)
    if pose == "attack":
        c.glow(64, 104, 12, (0.6, 2.0, 0.3), 1.8)
    return c


EXTRA_DRAW.update({"gummy": draw_gummy, "cupcake": draw_cupcake, "cakegolem": draw_cakegolem,
                   "ghost": draw_ghost, "skeleton": draw_skeleton, "shadowking": draw_shadowking,
                   "crawler": draw_crawler, "eyeorb": draw_eyeorb, "worm": draw_worm,
                   "shroomman": draw_shroomman, "puffer": draw_puffer, "spiderqueen": draw_spiderqueen})


# ---------------------------------------------------------------- עצמים לשלבים 9-12
def make_lollipop_tree():
    c = Canvas(80, 176)
    c.capsule(40, 174, 40, 64, 4, 4, (0.97, 0.97, 0.95), spec=0.6)
    pal = ((1.0, 0.25, 0.4), (1, 1, 1), (0.3, 0.75, 1.0), (1, 1, 1), (1.0, 0.85, 0.2), (1, 1, 1), (0.5, 0.9, 0.4))
    for k, col in enumerate(pal):
        r = 36 - k * 5
        c.ellipsoid(40, 38, r, r, col, spec=0.8, shine=30)
    c.glow(30, 26, 10, (0.3, 0.3, 0.3), 2, alpha=False)
    return c.sprite()


def make_gumdrops():
    c = Canvas(96, 48)
    for x, col in ((22, (1, 0.2, 0.3)), (48, (0.3, 0.9, 0.4)), (74, (0.7, 0.3, 0.95)), (36, (1, 0.7, 0.1)), (60, (0.2, 0.6, 1))):
        y = 40 if x in (22, 48, 74) else 30
        c.ellipsoid(x, y, 13, 11, col, emissive=0.25, spec=1.0, shine=30)
    return c.sprite()


def make_candelabra():
    frames = []
    for k in range(4):
        c = Canvas(64, 96)
        gold = (0.85, 0.65, 0.25)
        c.rbox(32, 92, 14, 4, gold, p=4, spec=0.9)
        c.capsule(32, 90, 32, 44, 3, 2.5, gold, spec=0.9)
        c.capsule(12, 44, 52, 44, 2.5, 2.5, gold, spec=0.9)
        rr = random.Random(k)
        for x in (12, 32, 52):
            c.capsule(x, 44, x, 30, 3.5, 3.5, (0.95, 0.92, 0.85), spec=0.3)
            c.glow(x + rr.uniform(-1, 1), 24 + rr.uniform(-1, 1), 8, (2.2, 1.2, 0.3), 1.4)
            c.glow(x, 25, 3, (2.4, 2.2, 1.6), 2)
        frames.append(c.sprite())
    return frames


def make_pumpkin():
    frames = []
    for k in range(4):
        c = Canvas(64, 56)
        for dx in (-14, 14, -7, 7, 0):
            c.ellipsoid(32 + dx, 34, 14, 18, (0.95, 0.45, 0.05), spec=0.5)
        c.capsule(32, 18, 34, 8, 3, 2.5, (0.3, 0.4, 0.1))
        fl = 1.6 + 0.4 * math.sin(k * 1.7)
        for side in (-1, 1):
            c.ellipsoid(32 + side * 9, 30, 4, 4, (1.0, 0.85, 0.2), emissive=fl, spec=0)
        c.ellipsoid(32, 42, 11, 4, (1.0, 0.8, 0.2), emissive=fl, spec=0)
        for x in (26, 32, 38):
            c.ellipsoid(x, 39, 1.8, 1.8, (0.95, 0.45, 0.05), spec=0.3)
        frames.append(c.sprite())
    return frames


def make_beacon():
    frames = []
    for k in range(4):
        c = Canvas(32, 160)
        c.rbox(16, 156, 10, 4, (0.3, 0.3, 0.33), p=4, spec=0.7)
        c.capsule(16, 154, 16, 20, 2.5, 2, (0.6, 0.6, 0.62), spec=0.8)
        for y in (60, 100, 140):
            c.capsule(6, y, 26, y - 20, 1, 1, (0.5, 0.5, 0.52), spec=0.6)
        on = k < 2
        c.ellipsoid(16, 16, 6, 6, (1.0, 0.15, 0.1), emissive=2.6 if on else 0.4, spec=0.8)
        if on:
            c.glow(16, 16, 16, (1.6, 0.2, 0.1), 2, alpha=False)
        frames.append(c.sprite())
    return frames


def make_boulder():
    c = Canvas(96, 64)
    c.ellipsoid(48, 40, 40, 24, (0.55, 0.26, 0.15), spec=0.2)
    c.ellipsoid(30, 30, 18, 14, (0.6, 0.3, 0.18), spec=0.2)
    c.ellipsoid(64, 46, 20, 14, (0.5, 0.24, 0.14), spec=0.2)
    return c.sprite()


def make_glow_mushroom():
    c = Canvas(96, 192)
    c.capsule(48, 190, 46, 70, 11, 9, (0.85, 0.82, 0.72), spec=0.3)
    c.ellipsoid(48, 70, 46, 12, (0.6, 0.65, 0.7), spec=0.2)
    c.ellipsoid(48, 56, 47, 28, (0.15, 0.45, 0.6), emissive=0.5, spec=0.7)
    rr = random.Random(8)
    for k in range(9):
        c.ellipsoid(48 + rr.uniform(-34, 34), rr.uniform(38, 62), rr.uniform(3, 6), rr.uniform(2, 4),
                    (0.5, 1.0, 1.0), emissive=1.8, spec=0.5)
    c.glow(48, 70, 40, (0.2, 0.6, 0.8), 2.0, alpha=False)
    return c.sprite()


def make_small_shrooms():
    c = Canvas(96, 48)
    rr = random.Random(12)
    for k in range(6):
        x = 12 + k * 14 + rr.uniform(-3, 3)
        h = rr.uniform(14, 30)
        c.capsule(x, 47, x, 47 - h, 2.2, 2, (0.85, 0.8, 0.7), spec=0.3)
        c.ellipsoid(x, 47 - h, 8, 5, (0.9, 0.3, 0.9), emissive=1.2, spec=0.6)
    return c.sprite()


def make_extra_props2(theme):
    if theme == "candy":
        return [make_lollipop_tree()] * 4, make_gumdrops()
    if theme == "castle":
        return make_candelabra(), make_pumpkin()
    if theme == "mars":
        return make_beacon(), make_boulder()
    if theme == "shroom":
        return [make_glow_mushroom()] * 4, make_small_shrooms()


# ---------------------------------------------------------------- אויבים לשלבים 13-16 (עיצובים מקוריים)


def draw_stormbird(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    body, wing, beak = (0.35, 0.4, 0.6), (0.25, 0.3, 0.5), (1.0, 0.8, 0.2)
    flap = math.sin(phase * 2) * 14
    for side in (-1, 1):
        prev = (64 + side * 16, 60)
        for k in range(1, 6):
            x = 64 + side * (16 + k * 9)
            y = 60 - flap * k / 5 + k * 3
            c.capsule(*prev, x, y, 9 - k, 8 - k, wing, spec=0.4)
            c.capsule(x, y, x + side * 2, y + 14, 3, 1, (0.5, 0.7, 1.0), emissive=0.8)
            prev = (x, y)
    c.capsule(64, 84, 64, 108, 8, 2, wing)
    c.ellipsoid(64, 66, 18, 22, body, spec=0.5)
    c.ellipsoid(64, 72, 10, 13, (0.75, 0.8, 0.95), spec=0.3)
    c.ellipsoid(64, 40, 14, 13, body, spec=0.5)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 7, 37, 3, 3, (0.6, 0.9, 1.0), emissive=2.0)
    op = 5 if pose == "attack" else 1
    c.capsule(64, 46, 64, 56 + op, 4, 1.5, beak, spec=0.6)
    for k in range(3):
        c.capsule(58 + k * 6, 28, 56 + k * 7, 14, 2, 0.8, (0.5, 0.7, 1.0), emissive=1.2)
    return c


def draw_cloudling(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    hot = pose == "attack"
    col = (0.55, 0.58, 0.7) if hot else (0.9, 0.92, 1.0)
    s = math.sin(phase)
    for x, y, r in ((40, 70, 22), (88, 70, 22), (64, 56, 30), (52, 80, 20), (76, 80, 20), (64, 46, 22)):
        c.ellipsoid(x + s * 2, y, r, r * 0.85, col, emissive=0.3, spec=0.2)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 10, 58, 4.5, 5, (0.2, 0.25, 0.4), spec=0.5)
        c.ellipsoid(64 + side * 10, 56, 1.6, 1.6, (1, 1, 1), emissive=1)
    c.ellipsoid(64, 72, 7 if hot else 4, 4 if hot else 2, (0.25, 0.25, 0.4), spec=0)
    if hot:
        for k in (-1, 0, 1):
            c.capsule(64 + k * 14, 96, 60 + k * 16, 110, 2.5, 1.5, (1.0, 1.0, 0.5), emissive=2.5)
            c.capsule(60 + k * 16, 110, 66 + k * 15, 124, 1.5, 0.8, (1.0, 1.0, 0.5), emissive=2.5)
    return c


def draw_thundergiant(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    skin, robe, cloud = (0.55, 0.65, 0.85), (0.22, 0.28, 0.5), (0.9, 0.92, 1.0)
    s = math.sin(phase)
    for side, sw in ((-1, s), (1, -s)):
        c.capsule(64 + side * 14, 84, 64 + side * 16 + sw * 3, 122, 10, 9, robe)
    for x in range(30, 100, 10):
        c.ellipsoid(x, 122, 10, 7, cloud, emissive=0.2)
    c.ellipsoid(64, 68, 30, 28, robe, spec=0.4)
    c.capsule(40, 48, 88, 92, 4, 4, (0.95, 0.8, 0.3), spec=0.8)
    up = pose == "attack"
    for side in (-1, 1):
        hx, hy = 64 + side * 40, (22 if up else 74)
        c.capsule(64 + side * 26, 50, hx, hy, 10, 8, skin)
        c.ellipsoid(hx, hy, 9, 9, skin)
        if up:
            c.glow(hx, hy - 8, 18, (1.4, 1.6, 2.4), 1.6)
    c.ellipsoid(64, 26, 16, 17, skin)
    for x, y, r in ((52, 40, 9), (64, 44, 11), (76, 40, 9), (58, 50, 8), (70, 50, 8), (64, 56, 7)):
        c.ellipsoid(x, y, r, r, cloud, emissive=0.3, spec=0.2)
    for x, y in ((50, 14), (64, 10), (78, 14)):
        c.ellipsoid(x, y, 9, 8, cloud, emissive=0.3, spec=0.2)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 7, 25, 3.4, 2.2, (1.0, 1.0, 0.6), emissive=2.6)
    return c


def draw_toysoldier(phase=0.0, pose="walk"):
    c = Canvas(128, 128)
    red, blue, gold, skin = (0.85, 0.12, 0.12), (0.12, 0.2, 0.6), (0.95, 0.78, 0.25), (0.95, 0.78, 0.65)
    s = math.sin(phase)
    for side, sw in ((-1, s), (1, -s)):
        c.rbox(64 + side * 8, 104 + sw * 2, 6, 16, blue, p=6, spec=0.5)
        c.rbox(64 + side * 8, 122, 7, 4, (0.08, 0.08, 0.08), p=4, spec=0.8)
    c.rbox(64, 70, 18, 20, red, p=6, spec=0.5)
    for y in (60, 70, 80):
        c.ellipsoid(64, y, 2.4, 2.4, gold, spec=0.9)
    c.capsule(47, 52, 81, 88, 2.5, 2.5, (1, 1, 1), spec=0.4)
    for side in (-1, 1):
        c.ellipsoid(64 + side * 19, 52, 6, 4, gold, spec=0.9)
    c.capsule(45, 54, 44, 82, 5, 4.5, red, spec=0.5)
    if pose == "attack":
        c.capsule(83, 54, 70, 60, 5, 4.5, red, spec=0.5)
