def make_enemy_frames(draw):
    walk = [draw(p).sprite() for p in (0.0, 1.57, 3.14, 4.71)]
    attack = draw(0.0, "attack").sprite()
    pain = Sprite(walk[0].rgb * 0.5 + 0.6, walk[0].a, walk[0].e)
    dying = [squash(walk[0], 0.7, 0.8), squash(walk[0], 0.42, 0.65)]
    pud = Canvas(128, 128)
    pud.ellipsoid(64, 122, 46, 6, (0.35, 0.02, 0.02), spec=0.8, shine=24)
    corpse = squash(walk[0], 0.22, 0.5)
    m = corpse.a[..., None]
    corpse = Sprite(pud.rgb * (1 - m) + corpse.rgb * m, np.maximum(pud.a, corpse.a), corpse.e * 0)
    return {"walk": walk, "attack": attack, "pain": pain, "dying": dying, "dead": corpse}


