def make_particles():
    c = Canvas(16, 16)
    c.ellipsoid(8, 8, 7, 7, (0.55, 0.02, 0.02), spec=0.7, shine=20)
    blood = c.sprite()
    c = Canvas(16, 16)
    c.glow(8, 8, 8, (2.5, 1.6, 0.6), 1.8)
    spark = c.sprite()
    c = Canvas(32, 32)
    d = np.hypot(c.X - 16, c.Y - 16) / 16
    c.a = (np.clip(1 - d, 0, 1) ** 2 * 0.45).astype(F32)
    c.rgb[:] = 0.35
    smoke = c.sprite()
    c = Canvas(64, 64)
    c.glow(32, 32, 32, (2.4, 0.9, 0.15), 1.6)
    c.glow(32, 32, 14, (2.0, 1.8, 1.0), 2.0)
    fireball = c.sprite()
    c = Canvas(64, 64)
    c.glow(32, 32, 32, (0.3, 1.1, 2.4), 1.6)
    c.glow(32, 32, 13, (1.4, 2.0, 2.2), 2.0)
    plasma = c.sprite()
    c = Canvas(64, 64)
    c.glow(32, 32, 32, (2.4, 0.3, 0.9), 1.8)
    c.glow(32, 32, 11, (2.2, 1.6, 1.8), 2.0)
    laser = c.sprite()
    c = Canvas(64, 64)
    c.glow(32, 32, 32, (0.6, 2.2, 0.3), 1.8)
    c.glow(32, 32, 11, (1.4, 2.2, 1.0), 2.0)
    acid = c.sprite()
    extra = {}
    for name, outer, core in (("snowball", (1.2, 1.3, 1.5), (2.0, 2.0, 2.2)), ("zapball", (1.6, 0.4, 1.8), (2.2, 1.6, 2.2)),
                              ("ink", (0.7, 0.2, 1.2), (1.0, 0.6, 1.5)), ("bolt", (2.2, 1.6, 0.4), (2.4, 2.2, 1.2))):
        c = Canvas(64, 64)
        c.glow(32, 32, 32, outer, 1.8)
        c.glow(32, 32, 11, core, 2.0)
        extra[name] = c.sprite()
    c = Canvas(64, 64)
    c.rbox(32, 32, 22, 22, (1.0, 0.3, 0.9), p=20, emissive=2.2)
    c.rbox(32, 32, 9, 9, (1.0, 1.0, 1.0), p=20, emissive=2.5)
    extra["pixel"] = c.sprite()
    c = Canvas(16, 16)
    c.glow(8, 8, 8, (1.8, 1.9, 2.2), 1.8)
    extra["snowp"] = c.sprite()
    c = Canvas(16, 16)
    c.rbox(8, 8, 6, 6, (1.0, 0.3, 0.9), p=20, emissive=2.4)
    extra["pixelp"] = c.sprite()
    for name, outer, core in (("ecto", (0.3, 1.5, 0.9), (1.4, 2.2, 1.8)), ("darkbolt", (1.0, 0.2, 2.0), (1.8, 1.2, 2.4)),
                              ("spore", (1.4, 0.4, 1.7), (2.0, 1.4, 2.2))):
        c = Canvas(64, 64)
        c.glow(32, 32, 32, outer, 1.8)
        c.glow(32, 32, 11, core, 2.0)
        extra[name] = c.sprite()
    c = Canvas(64, 64)
    for k, col in enumerate(((2, 0.4, 0.6), (0.4, 1.4, 2.2), (2.2, 2.0, 0.4), (0.5, 2.0, 0.6))):
        a = k * math.pi / 2
        c.capsule(32 + math.cos(a) * 6, 32 + math.sin(a) * 6, 32 + math.cos(a) * 18, 32 + math.sin(a) * 18, 4, 4,
                  (1, 1, 1), emissive=0)
        c.glow(32 + math.cos(a) * 12, 32 + math.sin(a) * 12, 12, col, 1.5)
    extra["sprinkle"] = c.sprite()
    for name, col in (("zapspark", (1.4, 0.5, 2.4)), ("sporep", (1.6, 0.6, 2.0))):
        c = Canvas(16, 16)
        c.glow(8, 8, 8, col, 1.8)
        extra[name] = c.sprite()
    c = Canvas(16, 16)
    c.glow(8, 8, 8, (0.6, 1.6, 2.6), 1.8)
    bspark = c.sprite()
    return {"blood": blood, "spark": spark, "smoke": smoke, "fireball": fireball,
            "plasma": plasma, "bspark": bspark, "laser": laser, "acid": acid, **extra}


NAIL = (0.92, 0.72, 0.62)
SLEEVE = (0.24, 0.27, 0.17)


def draw_arms(c, o=0, hx=140, hy=196, grip=74):
    """ידיים ושרוולים - משותף לכל הנשקים."""
    c.capsule(-10, 350, hx - 28, hy + 32 + o, 56, 36, SLEEVE, spec=0.12)
    c.capsule(hx - 40, hy + 42 + o, hx - 14, hy + 16 + o, 33, 30, tuple(v * 0.75 for v in SLEEVE), spec=0.1)
    c.ellipsoid(hx, hy + o, 28, 26, SKIN, spec=0.15)
    for i in range(4):
        y = hy - 44 + o + i * 15
        ex = hx + grip - abs(i - 1.5) * 7
        c.capsule(hx + 6, y + 6, ex, y, 9.5, 8.0, SKIN, spec=0.2)
        c.ellipsoid(ex, y, 5, 4, NAIL, spec=0.4)
    c.capsule(hx + 10, hy + 16 + o, hx + 46, hy + 28 + o, 10, 8, SKIN, spec=0.2)
    c.capsule(380, 350, 272, 326, 56, 38, SLEEVE, spec=0.12)
    c.ellipsoid(244, 322, 32, 22, SKIN, spec=0.15)


def make_flash(main, core):
    fl = Canvas(280, 280)
    ang = np.arctan2(fl.Y - 140, fl.X - 140)
    d = np.hypot(fl.X - 140, fl.Y - 140) / 140
    reach = 0.55 + 0.45 * np.abs(np.cos(ang * 4)) ** 3
    g = np.clip(1 - d / reach, 0, 1) ** 1.6
    fl.e = (g[..., None] * np.array(main, F32) + (g ** 4)[..., None] * np.array(core, F32)).astype(F32)
    fl.a = np.clip(g * 1.5, 0, 1).astype(F32)
    return fl.surface()


