# ======================================================================= סאונד
RATE = 22050


def make_sounds():
    try:
        pygame.mixer.init(RATE, -16, 1, 512)
    except pygame.error:
        return {}
    rng = np.random.default_rng(5)

    def env(n, p):
        return (1 - np.arange(n) / n) ** p

    def snd(x):
        x = np.clip(x, -1, 1)
        return pygame.mixer.Sound(buffer=array("h", (x * 30000).astype(np.int16).tolist()).tobytes())

    def tone(n, f0, f1):
        f = np.linspace(f0, f1, n)
        return np.sin(np.cumsum(f) * 2 * np.pi / RATE)

    n = int(RATE * 0.16)
    shot = rng.uniform(-1, 1, n) * env(n, 5) * 0.7 + tone(n, 120, 50) * env(n, 3) * 0.6
    n = int(RATE * 0.55)
    shotgun = rng.uniform(-1, 1, n) * env(n, 4) * 0.8 + tone(n, 90, 35) * env(n, 2) * 0.7
    n = int(RATE * 0.2)
    zap = tone(n, 1400, 300) * env(n, 1.5) * 0.35 + rng.uniform(-1, 1, n) * env(n, 4) * 0.1
    n = int(RATE * 0.45)
    screech = tone(n, 900, 1700) * np.sin(np.linspace(0, np.pi, n)) * 0.3 + rng.uniform(-1, 1, n) * env(n, 2) * 0.15
    n = int(RATE * 0.4)
    hiss = rng.uniform(-1, 1, n) * np.sin(np.linspace(0, np.pi, n)) * 0.3
    n = int(RATE * 1.3)
    rexroar = ((((np.arange(n) * np.linspace(70, 38, n) / RATE) % 1) * 2 - 1) * 0.5
               + rng.uniform(-1, 1, n) * 0.25) * np.sin(np.linspace(0, np.pi, n)) ** 0.5
    n = int(RATE * 0.28)
    stomp = tone(n, 55, 22) * env(n, 2.5) * 0.9 + rng.uniform(-1, 1, n) * env(n, 6) * 0.2
    n = int(RATE * 1.0)
    howl = tone(n, 380, 620) * np.sin(np.linspace(0, np.pi, n)) ** 0.6 * 0.35
    n = int(RATE * 1.6)
    th = rng.uniform(-1, 1, n)
    th = np.convolve(th, np.ones(40) / 40, mode="same") * 6
    thunder = th * env(n, 1.6) * 0.8
    n = int(RATE * 0.5)
    growl = (((np.arange(n) * 80 / RATE) % 1) * 2 - 1) * env(n, 1) * 0.35 + rng.uniform(-1, 1, n) * env(n, 2) * 0.15
    n = int(RATE * 0.7)
    roar = (((np.arange(n) * np.linspace(60, 45, n) / RATE) % 1) * 2 - 1) * env(n, 1) * 0.45
    n = int(RATE * 0.3)
    hurt = tone(n, 260, 110) * env(n, 1.5) * 0.5
    n = int(RATE * 0.22)
    pick = tone(n, 500, 1400) * env(n, 0.5) * 0.35
    n = int(RATE * 0.08)
    click = rng.uniform(-1, 1, n) * env(n, 3) * 0.3
    n = int(RATE * 0.8)
    death = (((np.arange(n) * np.linspace(140, 40, n) / RATE) % 1) * 2 - 1) * env(n, 1) * 0.4
    n = int(RATE * 0.5)
    boom = rng.uniform(-1, 1, n) * env(n, 3) * 0.6 + tone(n, 70, 30) * env(n, 2) * 0.5
    n = int(RATE * 0.35)
    whoosh = rng.uniform(-1, 1, n) * np.sin(np.linspace(0, np.pi, n)) * 0.25
    n = int(RATE * 0.25)
    pump = np.concatenate([rng.uniform(-1, 1, n // 2) * env(n // 2, 6) * 0.4,
                           rng.uniform(-1, 1, n - n // 2) * env(n - n // 2, 6) * 0.5])
    return {k: snd(v) for k, v in dict(shot=shot, shotgun=shotgun, zap=zap,
                                        screech=screech, hiss=hiss, rexroar=rexroar, stomp=stomp,
                                        howl=howl, thunder=thunder, growl=growl, roar=roar, hurt=hurt, pickup=pick,
                                        click=click, death=death, boom=boom, whoosh=whoosh,
                                        pump=pump).items()}


# ======================================================================= עולם


class World:
    def __init__(self, level):
        w = max(map(len, level))
        rows = [r.ljust(w, "1") for r in level]
        self.h, self.w = len(rows), w
        self.chars = rows
        self.G = np.array([[int(ch) if ch in "123" else 0 for ch in r] for r in rows], np.int32)
        ft = np.zeros((self.h, w), np.int32)
        for y, r in enumerate(rows):
            for x, ch in enumerate(r):
                if ch in ",G":
                    ft[y, x] = 1
                elif ch == "~":
                    ft[y, x] = 2
                elif ch in "AHP" or ch in ENEMY_CHARS:
                    nb = [rows[y + dy][x + dx] for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1))]
                    if "," in nb:
                        ft[y, x] = 1
        self.FT = ft
        self.obstacles = []

    def wall(self, x, y):
        ix, iy = int(x), int(y)
        if ix < 0 or iy < 0 or ix >= self.w or iy >= self.h:
            return True
        return self.G[iy, ix] > 0

    def free(self, x, y, r):
        if (self.wall(x - r, y - r) or self.wall(x + r, y - r)
                or self.wall(x - r, y + r) or self.wall(x + r, y + r)):
            return False
        for ox, oy in self.obstacles:
            if (x - ox) ** 2 + (y - oy) ** 2 < (r + 0.22) ** 2:
                return False
        return True

    def slide(self, ent, dx, dy, r):
        if self.free(ent.x + dx, ent.y, r):
            ent.x += dx
        if self.free(ent.x, ent.y + dy, r):
            ent.y += dy

    def cast(self, px, py, rdx, rdy):
        """DDA וקטורי - מטיל את כל הקרניים במקביל."""
        rdx = np.asarray(rdx, np.float64)
        rdy = np.asarray(rdy, np.float64)
        n = len(rdx)
        mx = np.full(n, int(px), np.int32)
        my = np.full(n, int(py), np.int32)
        with np.errstate(divide="ignore"):
            ddx = np.where(rdx == 0, 1e30, np.abs(1 / rdx))
            ddy = np.where(rdy == 0, 1e30, np.abs(1 / rdy))
        stx = np.where(rdx < 0, -1, 1).astype(np.int32)
        sty = np.where(rdy < 0, -1, 1).astype(np.int32)
        sdx = np.where(rdx < 0, (px - mx) * ddx, (mx + 1 - px) * ddx)
        sdy = np.where(rdy < 0, (py - my) * ddy, (my + 1 - py) * ddy)
        side = np.zeros(n, np.int32)
        kind = np.zeros(n, np.int32)
        active = np.ones(n, bool)
        for _ in range(96):
            xs = active & (sdx < sdy)
            ys = active & ~(sdx < sdy)
            sdx = np.where(xs, sdx + ddx, sdx)
            mx = np.where(xs, mx + stx, mx)
            sdy = np.where(ys, sdy + ddy, sdy)
            my = np.where(ys, my + sty, my)
            side = np.where(xs, 0, np.where(ys, 1, side))
            k = self.G[np.clip(my, 0, self.h - 1), np.clip(mx, 0, self.w - 1)]
            hit = active & (k > 0)
            kind = np.where(hit, k, kind)
            active &= ~hit
            if not active.any():
                break
        kind = np.where(kind == 0, 1, kind)
        dist = np.where(side == 0, sdx - ddx, sdy - ddy)
        return dist, kind, side, stx, sty

    def ray_dist(self, x, y, angle):
        d, *_ = self.cast(x, y, [math.cos(angle)], [math.sin(angle)])
        return float(d[0])

    def line_of_sight(self, x0, y0, x1, y1):
        dist = math.hypot(x1 - x0, y1 - y0)
        return self.ray_dist(x0, y0, math.atan2(y1 - y0, x1 - x0)) >= dist


