    STATS = KINDS

    def __init__(self, x, y, kind, diff=None):
        diff = diff or LEVELS[0]["diff"]
        self.x, self.y, self.kind = x, y, kind
        self.z = 0.0
        self.seed = random.random() * 10
        st = self.KINDS[kind]
        self.st = st
        self.hp = self.max_hp = st["hp"] * diff["hp"] * EASY["hp"] * (EASY["boss_hp"] if st.get("boss") else 1.0)
        self.speed, self.radius = st["speed"] * diff["speed"] * EASY["speed"], st["radius"]
        self.mr = min(0.45, self.radius * 0.8)      # רדיוס תנועה (כדי לעבור במסדרונות)
        self.height, self.pain_chance = st["height"], st["pain"]
        self.state = "idle"
        self.timer = 0.0
        self.cool = random.uniform(0.8, 2.0)
        self.anim = random.random() * 4
        self.alerted = False
        self.fired = 0
        self.step_t = 0.0

    @property
    def alive(self):
        return self.state not in ("dying", "dead")

    def update(self, dt, g):
        p = g.player
        st = self.st
        self.timer -= dt
        hov = 0.38 if self.kind == "drone" else st.get("hover")
        if hov is not None:          # מרחף/שוחה, ונופל כשמת
            if self.alive:
                self.z = hov + 0.07 * math.sin(g.time * 3 + self.seed)
            else:
                self.z = max(0.0, self.z - dt * 2.5)
        elif st.get("hop"):          # קוביה קופצת
            self.z = abs(math.sin(self.anim * 1.6)) * 0.35 if self.alive and self.state == "chase" else max(0.0, self.z - dt * 3)
        if self.state == "dying":
            if self.timer <= 0:
                self.state = "dead"
            return
        if self.state == "dead":
            return
        dx, dy = p.x - self.x, p.y - self.y
        dist = math.hypot(dx, dy) or 1e-6
        los = dist < 18 and g.world.line_of_sight(self.x, self.y, p.x, p.y)
        if los and not self.alerted:
            self.alerted = True
            g.play(st["alert"], dist)
            if st.get("boss"):
                g.shake = max(g.shake, 0.5)
                g.say(g.tr("boss_alert", name=g.tr("boss_" + self.kind)), 2.5)
        self.cool -= dt
        if self.state == "pain":
            if self.timer <= 0:
                self.state = "chase"
            return
        if self.state == "attack":
            if st["mode"] == "ranged" and self.fired < st["burst"] and self.timer < 0.42 - self.fired * 0.14:
                self.fired += 1
                g.spawn_fireball(self, st["shot"])
            if self.timer <= 0:
                self.state = "chase"
            return
        if not self.alerted or g.state != "play":
            return
        self.state = "chase"
        if dist > st["stop"]:
            boost = 1.35 if self.kind == "raptor" and dist < 4 else 1.0   # ראפטור מזנק כשקרוב
            sp = self.speed * boost * dt
            if st.get("phase"):      # רוח רפאים עוברת דרך קירות
                self.x = min(g.world.w - 1.5, max(1.5, self.x + dx / dist * sp))
                self.y = min(g.world.h - 1.5, max(1.5, self.y + dy / dist * sp))
            else:
                g.world.slide(self, dx / dist * sp, dy / dist * sp, self.mr)
            self.anim += dt * self.speed * 1.6
            if st.get("teleport") and random.random() < dt * 0.25:     # באג שקופץ ממקום למקום
                for _ in range(8):
                    nx, ny = self.x + random.uniform(-3, 3), self.y + random.uniform(-3, 3)
                    if g.world.free(nx, ny, self.mr):
                        g.emit(self.x, self.y, 0.5, "pixelp", 10, 2.0, 0.4, 0.06, 1.5)
                        self.x, self.y = nx, ny
                        g.emit(nx, ny, 0.5, "pixelp", 10, 2.0, 0.4, 0.06, 1.5)
                        break
            if st.get("stomp"):
                self.step_t += dt
                if self.step_t > 0.5:
                    self.step_t = 0
                    g.play("stomp", dist)
                    g.shake = max(g.shake, 0.18 * max(0.0, 1 - dist / 14))
        if self.cool <= 0 and los and dist < st["range"]:
            cm = g.diff["cool"] * EASY["cool"]
            self.cool = random.uniform(*st["cool"]) * cm
            if st["mode"] == "ranged":
                self.state, self.timer, self.fired = "attack", 0.55, 0
                if self.kind == "imp":
                    g.play("growl", dist)
            else:
                self.state, self.timer = "attack", 0.45
                g.hurt_player(random.randint(*st["dmg"]) * g.diff["dmg"], self.x, self.y)
                g.play(st["alert"], dist)
                if st.get("boss"):
                    g.shake = max(g.shake, 0.45)

    def image(self, frames):
        f = frames[self.kind]
        if self.state == "dead":
            return f["dead"]
        if self.state == "dying":
            return f["dying"][0 if self.timer > 0.22 else 1]
        if self.state == "pain":
            return f["pain"]
        if self.state == "attack":
            return f["attack"]
        return f["walk"][int(self.anim) % 4]


